-- =============================================================================
-- V011  orders — cases, orders, order items and everything hanging off them
-- =============================================================================
-- Owning module: Orders (CP / Connect ordering, order desk, restoration and
-- iSmile flows). Baseline: v2 orders schema (V010 + V039 + V041-V043), with the
-- v3 changes from V3_DESIGN.md section S "orders":
--   N cases, case_pairing_candidates (Q3, U8)
--   A orders (case_id NOT NULL; placeholder client contact, U7)
--   A order_items (parent_item_id, item_role, restoration_stage, hold_type,
--     hold_reason_id, zero-charge rule, legacy_key widened to 200)
--   A order_status_history (actor_role_id)
--   K order_item_field_values, order_comments, order_locks, order_lock_history,
--     projects, shopping_carts, shopping_cart_items, fulfilments, download_tracking
--   N order_item_decisions, confirmation_links, order_item_dependencies,
--     order_item_assignments, order_item_ai_plans, pre_shipping_instructions
-- Child tables that had no tenant_id in v2 get one, defaulting to
-- core.fn_current_tenant() so the ETL (which sets app.tenant_id) keeps working
-- with its v2 column lists. Cross-schema foreign keys are in
-- migrations/fk/orders.sql (assembled into V090). Business triggers (totals,
-- locks, financial freeze, order numbering) are V100/V110, not here.
-- =============================================================================


-- =============================================================================
-- orders.projects
-- =============================================================================
CREATE TABLE orders.projects (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id           bigint NOT NULL DEFAULT core.fn_current_tenant(),
    code                varchar(80) NOT NULL,
    name                varchar(200) NOT NULL,
    description         text,
    is_active           boolean NOT NULL DEFAULT true,
    legacy_id           bigint,
    legacy_source       varchar(64),
    legacy_key          varchar(200),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    created_by_user_id  bigint,
    updated_by_user_id  bigint,
    CONSTRAINT pk_projects PRIMARY KEY (id),
    CONSTRAINT uq_projects__tenant_id__code UNIQUE (tenant_id, code)
);
CREATE UNIQUE INDEX uq_projects__legacy ON orders.projects (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE orders.projects IS 'Partner programme or study that groups orders arriving through it (legacy SourceProjects). One row per programme per tenant; orders point at it through orders.orders.project_id. Master data: deactivated with is_active, never deleted while orders reference it.';
COMMENT ON COLUMN orders.projects.id IS 'Surrogate key of the project; system-generated.';
COMMENT ON COLUMN orders.projects.tenant_id IS 'Tenant that owns the project (core.tenants); every query is scoped to it by row-level security.';
COMMENT ON COLUMN orders.projects.code IS 'Stable short code of the programme, unique per tenant; migrated from SourceProjects (slugged name when no code exists).';
COMMENT ON COLUMN orders.projects.name IS 'Display name of the programme or study shown to order-desk staff; migrated from SourceProjects.';
COMMENT ON COLUMN orders.projects.description IS 'Free-text description of the programme for staff. User input. NULL = no description recorded.';
COMMENT ON COLUMN orders.projects.is_active IS 'true = new orders may be attached to this project; false = retired, kept for the orders that already reference it.';
COMMENT ON COLUMN orders.projects.legacy_id IS 'SourceProjects.ID this row was migrated from. NULL = created in threeddx3.';
COMMENT ON COLUMN orders.projects.legacy_source IS 'Legacy table the row came from (''SourceProjects''). NULL = created in threeddx3.';
COMMENT ON COLUMN orders.projects.legacy_key IS 'Composite legacy key when one id is not enough. NULL = legacy_id alone identifies the row (always so for SourceProjects).';
COMMENT ON COLUMN orders.projects.created_at IS 'UTC instant the row was created (migration time for migrated rows). [AUDIT]';
COMMENT ON COLUMN orders.projects.updated_at IS 'UTC instant of the last change; maintained by trg_projects__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN orders.projects.created_by_user_id IS 'iam.users.id of the creator. No FK by design (audit actor, survives user deletion). NULL = system or migration. [AUDIT]';
COMMENT ON COLUMN orders.projects.updated_by_user_id IS 'iam.users.id of the last editor. No FK by design (audit actor). NULL = system or migration, or never updated. [AUDIT]';
COMMENT ON CONSTRAINT pk_projects ON orders.projects IS 'One row per project.';
COMMENT ON CONSTRAINT uq_projects__tenant_id__code ON orders.projects IS 'A project code identifies one programme within a tenant.';
COMMENT ON INDEX orders.uq_projects__legacy IS 'Every migrated project is traceable to its SourceProjects row and cannot be loaded twice.';

CREATE TRIGGER trg_projects__touch_updated_at BEFORE UPDATE ON orders.projects
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_projects__touch_updated_at ON orders.projects IS 'Sets updated_at and updated_by_user_id on every update (core.fn_touch_updated_at).';


-- =============================================================================
-- orders.cases
-- =============================================================================
CREATE TABLE orders.cases (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id           bigint NOT NULL DEFAULT core.fn_current_tenant(),
    uuid                uuid NOT NULL DEFAULT gen_random_uuid(),
    case_code           varchar(40) NOT NULL,
    contact_id          bigint NOT NULL,
    patient_id          bigint,
    pairing_method      varchar(40) NOT NULL DEFAULT 'single',
    pairing_confidence  numeric(4,3),
    pairing_evidence    jsonb,
    legacy_id           bigint,
    legacy_source       varchar(64),
    legacy_key          varchar(200),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    created_by_user_id  bigint,
    updated_by_user_id  bigint,
    CONSTRAINT pk_cases PRIMARY KEY (id),
    CONSTRAINT uq_cases__uuid UNIQUE (uuid),
    CONSTRAINT uq_cases__tenant_id__case_code UNIQUE (tenant_id, case_code),
    CONSTRAINT ck_cases__pairing_method CHECK (pairing_method IN ('single', 'auto_split_arch', 'manual')),
    CONSTRAINT ck_cases__pairing_confidence_range CHECK (pairing_confidence IS NULL OR pairing_confidence BETWEEN 0 AND 1),
    CONSTRAINT ck_cases__pairing_provenance CHECK (
           (pairing_method = 'single' AND pairing_confidence IS NULL)
        OR (pairing_method = 'auto_split_arch' AND pairing_confidence IS NOT NULL AND pairing_evidence IS NOT NULL)
        OR  pairing_method = 'manual')
);
CREATE INDEX ix_cases__tenant_id__contact_id ON orders.cases (tenant_id, contact_id);
CREATE INDEX ix_cases__patient_id ON orders.cases (patient_id) WHERE patient_id IS NOT NULL;
CREATE INDEX ix_cases__tenant_id__created_at__id ON orders.cases (tenant_id, created_at, id);
CREATE UNIQUE INDEX uq_cases__legacy ON orders.cases (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE orders.cases IS 'Clinical case above one or more orders (Q3: no legacy case id exists). One row per case: a single order is a one-order case; a split-arch submission (one order per arch) becomes two orders under one case. Every order belongs to exactly one case (orders.orders.case_id). Historical pairs are auto-linked by the ETL only when the evidence is unambiguous; ambiguous pairs stay in separate single cases and are listed in orders.case_pairing_candidates for review (U8). Not soft-deleted; a case lives as long as its orders. Contains PII.';
COMMENT ON COLUMN orders.cases.id IS 'Surrogate key of the case; system-generated.';
COMMENT ON COLUMN orders.cases.tenant_id IS 'Tenant that owns the case (core.tenants); row-level security scope.';
COMMENT ON COLUMN orders.cases.uuid IS 'Public identifier of the case used by the API and portals instead of the numeric id.';
COMMENT ON COLUMN orders.cases.case_code IS 'Human-readable case reference shown to staff and clients, unique per tenant. System-generated (for migrated cases derived by the ETL from the first order number). Exact format TO CONFIRM with the business.';
COMMENT ON COLUMN orders.cases.contact_id IS 'Client (crm.contacts) who owns the case: the ordering doctor/practice of its orders. May be the tenant''s placeholder "Unknown client" contact for legacy orders whose DocID has no account (U7).';
COMMENT ON COLUMN orders.cases.patient_id IS 'Pseudonymous patient (clinical.patients) the case treats; identity is in clinical.patient_identities. NULL = no patient recorded on the orders (e.g. software, equipment, misc orders).';
COMMENT ON COLUMN orders.cases.pairing_method IS 'How the case''s orders were grouped: ''single'' = one order, no pairing; ''auto_split_arch'' = two or more orders linked automatically as one split-arch submission because the evidence was unambiguous; ''manual'' = linked by a person (accepted candidate in case_pairing_candidates or created together in the portal).';
COMMENT ON COLUMN orders.cases.pairing_confidence IS 'Score 0-1 of the automatic pairing inference (1 = certain). Calculated by the ETL / pairing job. NULL = single-order case, or a manual pairing made without a score.';
COMMENT ON COLUMN orders.cases.pairing_evidence IS 'Inference provenance kept per Q3: which signals matched (same patient name, same doctor, same scanning centre, creation-time gap, arch per order) and the rule version, as JSON. Not filtered or reported on. May quote patient names. NULL = no inference was made (single or manual case). [PHI-RISK]';
COMMENT ON COLUMN orders.cases.legacy_id IS 'Orders.ID of the earliest legacy order the ETL built this case from. NULL = case created in threeddx3.';
COMMENT ON COLUMN orders.cases.legacy_source IS 'Derivation label ''Orders:case'' = built by the ETL from legacy Orders (cases are derived, not 1:1 with a legacy table, so reconciliation does not pair them with Orders). NULL = created in threeddx3.';
COMMENT ON COLUMN orders.cases.legacy_key IS 'Composite legacy key when one id is not enough. NULL = legacy_id alone identifies the case.';
COMMENT ON COLUMN orders.cases.created_at IS 'UTC instant the case was created (for migrated cases: migration time; the order dates carry the business time). [AUDIT]';
COMMENT ON COLUMN orders.cases.updated_at IS 'UTC instant of the last change; maintained by trg_cases__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN orders.cases.created_by_user_id IS 'iam.users.id of the creator. No FK by design (audit actor). NULL = system or migration. [AUDIT]';
COMMENT ON COLUMN orders.cases.updated_by_user_id IS 'iam.users.id of the last editor. No FK by design (audit actor). NULL = system or migration, or never updated. [AUDIT]';
COMMENT ON CONSTRAINT pk_cases ON orders.cases IS 'One row per case.';
COMMENT ON CONSTRAINT uq_cases__uuid ON orders.cases IS 'The public case identifier is globally unique.';
COMMENT ON CONSTRAINT uq_cases__tenant_id__case_code ON orders.cases IS 'A case code identifies one case within a tenant.';
COMMENT ON CONSTRAINT ck_cases__pairing_method ON orders.cases IS 'Pairing method is one of single, auto_split_arch, manual.';
COMMENT ON CONSTRAINT ck_cases__pairing_confidence_range ON orders.cases IS 'A pairing confidence is a fraction between 0 and 1.';
COMMENT ON CONSTRAINT ck_cases__pairing_provenance ON orders.cases IS 'A single-order case has no confidence score; an automatic split-arch pairing must keep its confidence and its evidence (Q3: the inference provenance is retained); a manual pairing may carry either.';
COMMENT ON INDEX orders.ix_cases__tenant_id__contact_id IS 'Cases of one client (client portal case list); covers the contact FK.';
COMMENT ON INDEX orders.ix_cases__patient_id IS 'Cases of one patient (patient history, GDPR export); covers the patient FK.';
COMMENT ON INDEX orders.ix_cases__tenant_id__created_at__id IS 'Stable keyset pagination of cases by creation time.';
COMMENT ON INDEX orders.uq_cases__legacy IS 'Every migrated case is traceable to the legacy order it was built from and cannot be loaded twice.';

CREATE TRIGGER trg_cases__touch_updated_at BEFORE UPDATE ON orders.cases
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_cases__touch_updated_at ON orders.cases IS 'Sets updated_at and updated_by_user_id on every update (core.fn_touch_updated_at).';


-- =============================================================================
-- orders.orders
-- =============================================================================
CREATE TABLE orders.orders (
    id                        bigint GENERATED BY DEFAULT AS IDENTITY,
    uuid                      uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id                 bigint NOT NULL DEFAULT core.fn_current_tenant(),
    case_id                   bigint NOT NULL,
    order_number              bigint NOT NULL,
    order_reference           varchar(50),
    contact_id                bigint NOT NULL,
    scan_center_contact_id    bigint,
    referring_contact_id      bigint,
    sales_rep_user_id         bigint,
    patient_id                bigint,
    project_id                bigint,
    status                    varchar(50) NOT NULL DEFAULT 'draft',
    priority                  varchar(20) NOT NULL DEFAULT 'normal',
    currency_code             core.currency_code NOT NULL,
    subtotal_amount           core.money_amount NOT NULL DEFAULT 0,
    discount_amount           core.money_amount NOT NULL DEFAULT 0,
    voucher_amount            core.money_amount NOT NULL DEFAULT 0,
    adjustment_amount         core.money_amount NOT NULL DEFAULT 0,
    adjustment_reason         text,
    total_amount              core.money_amount NOT NULL DEFAULT 0,
    billing_address_id        bigint,
    shipping_address_id       bigint,
    client_comment            text,
    internal_comment          text,
    pre_shipping_instructions text,
    source_channel            varchar(50),
    is_third_party            boolean NOT NULL DEFAULT false,
    is_testing                boolean NOT NULL DEFAULT false,
    surgery_date              date,
    due_at                    timestamptz,
    submitted_at              timestamptz,
    confirmed_at              timestamptz,
    completed_at              timestamptz,
    closed_at                 timestamptz,
    closed_by_user_id         bigint,
    cancelled_at              timestamptz,
    metadata                  jsonb NOT NULL DEFAULT '{}'::jsonb,
    legacy_id                 bigint,
    legacy_source             varchar(64),
    legacy_key                varchar(200),
    created_at                timestamptz NOT NULL DEFAULT now(),
    updated_at                timestamptz NOT NULL DEFAULT now(),
    created_by_user_id        bigint,
    updated_by_user_id        bigint,
    deleted_at                timestamptz,
    CONSTRAINT pk_orders PRIMARY KEY (id),
    CONSTRAINT uq_orders__uuid UNIQUE (uuid),
    CONSTRAINT uq_orders__tenant_id__order_number UNIQUE (tenant_id, order_number),
    CONSTRAINT fk_orders__case_id FOREIGN KEY (case_id) REFERENCES orders.cases (id) ON DELETE RESTRICT,
    CONSTRAINT fk_orders__project_id FOREIGN KEY (project_id) REFERENCES orders.projects (id) ON DELETE SET NULL,
    CONSTRAINT ck_orders__status CHECK (status IN ('draft', 'submitted', 'pending_information', 'in_review', 'confirmed',
        'in_design', 'awaiting_approval', 'in_production', 'quality_check', 'ready_to_ship', 'shipped', 'delivered',
        'completed', 'on_hold', 'cancelled', 'not_indicated')),
    CONSTRAINT ck_orders__priority CHECK (priority IN ('normal', 'rush', 'express', 'fast_track')),
    CONSTRAINT ck_orders__total_consistent CHECK (total_amount = subtotal_amount - discount_amount - voucher_amount + adjustment_amount),
    CONSTRAINT ck_orders__amounts_non_negative CHECK (legacy_id IS NOT NULL
        OR (subtotal_amount >= 0 AND discount_amount >= 0 AND voucher_amount >= 0 AND total_amount >= 0))
);
CREATE INDEX ix_orders__tenant_id__created_at__id ON orders.orders (tenant_id, created_at, id);
CREATE INDEX ix_orders__case_id ON orders.orders (case_id);
CREATE INDEX ix_orders__tenant_id__contact_id__created_at ON orders.orders (tenant_id, contact_id, created_at DESC) WHERE deleted_at IS NULL;
CREATE INDEX ix_orders__tenant_id__status__due_at__open ON orders.orders (tenant_id, status, due_at)
    WHERE status NOT IN ('completed', 'cancelled', 'not_indicated') AND deleted_at IS NULL;
CREATE INDEX ix_orders__patient_id ON orders.orders (patient_id) WHERE patient_id IS NOT NULL;
CREATE INDEX ix_orders__scan_center_contact_id ON orders.orders (scan_center_contact_id) WHERE scan_center_contact_id IS NOT NULL;
CREATE INDEX ix_orders__referring_contact_id ON orders.orders (referring_contact_id) WHERE referring_contact_id IS NOT NULL;
CREATE INDEX ix_orders__sales_rep_user_id__created_at ON orders.orders (sales_rep_user_id, created_at DESC) WHERE sales_rep_user_id IS NOT NULL;
CREATE INDEX ix_orders__project_id ON orders.orders (project_id) WHERE project_id IS NOT NULL;
CREATE INDEX ix_orders__billing_address_id ON orders.orders (billing_address_id) WHERE billing_address_id IS NOT NULL;
CREATE INDEX ix_orders__shipping_address_id ON orders.orders (shipping_address_id) WHERE shipping_address_id IS NOT NULL;
CREATE INDEX ix_orders__closed_by_user_id ON orders.orders (closed_by_user_id) WHERE closed_by_user_id IS NOT NULL;
CREATE INDEX ix_orders__order_reference_trgm ON orders.orders USING gin (order_reference public.gin_trgm_ops) WHERE order_reference IS NOT NULL;
CREATE UNIQUE INDEX uq_orders__legacy ON orders.orders (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE orders.orders IS 'One submission by a client (legacy Orders row): the commercial and clinical envelope around one or more order items. Belongs to exactly one case (split-arch submissions are two orders under one case). Service-family specifics live on orders.order_items, not on parallel tables. Soft-deleted with deleted_at; financial totals are maintained from the items by V110 triggers and frozen once invoiced. Contains PII.';
COMMENT ON COLUMN orders.orders.id IS 'Surrogate key of the order; system-generated.';
COMMENT ON COLUMN orders.orders.uuid IS 'Public identifier of the order used by the API and portals.';
COMMENT ON COLUMN orders.orders.tenant_id IS 'Tenant that owns the order (core.tenants); row-level security scope.';
COMMENT ON COLUMN orders.orders.case_id IS 'Case this order belongs to (orders.cases). Every order has a case: a lone order is a one-order case; split-arch orders share one. Set by the ETL for migrated orders (Q3/U8) and by order creation in the portals.';
COMMENT ON COLUMN orders.orders.order_number IS 'Order number shown to clients and staff, unique per tenant. Migrated 1:1 from legacy Orders.ID so existing references keep working; new numbers are assigned by the V110 numbering trigger.';
COMMENT ON COLUMN orders.orders.order_reference IS 'Client''s own reference for the order, free text typed at submission; often contains the patient''s name. Searchable by trigram. NULL = no reference given. [PHI-RISK]';
COMMENT ON COLUMN orders.orders.contact_id IS 'Ordering client (crm.contacts: doctor or practice account) who is billed by default. For legacy orders whose DocID has no account this is the tenant''s placeholder "Unknown client" contact (crm.contacts.is_placeholder = true, user decision U7), so the order is kept and traceable instead of dropped.';
COMMENT ON COLUMN orders.orders.scan_center_contact_id IS 'Scanning centre (crm.contacts) that submitted the scan on the doctor''s behalf, distinct from the ordering client. NULL = submitted directly by the client.';
COMMENT ON COLUMN orders.orders.referring_contact_id IS 'Contact who referred the case to 3DDX (crm.contacts). NULL = no referrer recorded.';
COMMENT ON COLUMN orders.orders.sales_rep_user_id IS 'Staff user (iam.users) credited as sales representative for the order. NULL = no sales rep assigned.';
COMMENT ON COLUMN orders.orders.patient_id IS 'Pseudonymous patient (clinical.patients); identity is in clinical.patient_identities. Set by ETL stage 40 for migrated orders. NULL = order without a patient (equipment, software, misc) or not yet linked.';
COMMENT ON COLUMN orders.orders.project_id IS 'Partner programme the order arrived through (orders.projects). NULL = not part of a programme.';
COMMENT ON COLUMN orders.orders.status IS 'Client-facing summary status of the whole order (detailed per-item state lives in workflow.workflow_instances): ''draft'' = being prepared, not submitted; ''submitted'' = received from the client; ''pending_information'' = waiting on the client for files or answers; ''in_review'' = being checked by the order desk; ''confirmed'' = accepted for work; ''in_design'' = design/planning in progress; ''awaiting_approval'' = design sent, waiting for the client''s decision; ''in_production'' = being manufactured; ''quality_check'' = in QC; ''ready_to_ship'' = passed QC, waiting for dispatch; ''shipped'' = handed to the courier or delivered digitally; ''delivered'' = received by the client; ''completed'' = finished, nothing outstanding; ''on_hold'' = paused (customer or internal, see order_items.hold_type); ''cancelled'' = withdrawn; ''not_indicated'' = rejected as not clinically indicated.';
COMMENT ON COLUMN orders.orders.priority IS 'Turnaround priority chosen by the client: ''normal'' = standard turnaround; ''rush'' = rush fee, shortened turnaround; ''express'' = fastest paid turnaround; ''fast_track'' = internal priority lane without a rush fee.';
COMMENT ON COLUMN orders.orders.currency_code IS 'Currency of every amount on the order and its items (core.currencies); decoded from legacy Orders.Currency symbols by the ETL.';
COMMENT ON COLUMN orders.orders.subtotal_amount IS 'Sum of the items'' gross amounts (unit price x quantity + field surcharges) in currency_code. Calculated by the V110 order-total trigger. [FINANCIAL]';
COMMENT ON COLUMN orders.orders.discount_amount IS 'Sum of the items'' discounts in currency_code. Calculated from the items. [FINANCIAL]';
COMMENT ON COLUMN orders.orders.voucher_amount IS 'Sum of voucher credit applied to the items in currency_code (ledger: vouchers.voucher_transactions). Calculated from the items. [FINANCIAL]';
COMMENT ON COLUMN orders.orders.adjustment_amount IS 'Manual order-level adjustment in currency_code: positive = surcharge, negative = goodwill credit. User input with adjustment_reason. [FINANCIAL]';
COMMENT ON COLUMN orders.orders.adjustment_reason IS 'Why the manual adjustment was made. User input. NULL = no adjustment, or none explained in legacy data.';
COMMENT ON COLUMN orders.orders.total_amount IS 'Amount payable for the order in currency_code = subtotal - discount - voucher + adjustment (ck_orders__total_consistent). Calculated. [FINANCIAL]';
COMMENT ON COLUMN orders.orders.billing_address_id IS 'Client address used for invoicing (crm.contact_addresses). NULL = use the client''s default billing address.';
COMMENT ON COLUMN orders.orders.shipping_address_id IS 'Client address the goods ship to (crm.contact_addresses). NULL = digital-only order, or use the client''s default shipping address.';
COMMENT ON COLUMN orders.orders.client_comment IS 'Free-text note the client wrote when submitting; may describe the patient. Migrated from Orders comments. NULL = none. [PHI-RISK]';
COMMENT ON COLUMN orders.orders.internal_comment IS 'Staff-only note on the order; may describe the patient. NULL = none. [PHI-RISK]';
COMMENT ON COLUMN orders.orders.pre_shipping_instructions IS 'Kept from v2 for compatibility: current pre-shipping instruction text. The versioned record with author is orders.pre_shipping_instructions (v3), which is authoritative; this copy is written by the application with the newest version. NULL = no instruction. [SNAPSHOT] [PHI-RISK]';
COMMENT ON COLUMN orders.orders.source_channel IS 'Where the order was placed (e.g. connect, cp, integration partner name). System-generated. NULL = unknown (legacy orders without a channel).';
COMMENT ON COLUMN orders.orders.is_third_party IS 'true = the order is fulfilled for or through a third party (legacy third-party flag); affects billing and reporting.';
COMMENT ON COLUMN orders.orders.is_testing IS 'true = test order created by staff; excluded from billing and business reports.';
COMMENT ON COLUMN orders.orders.surgery_date IS 'Planned surgery date given by the client (calendar date, no time zone). Drives due dates of surgical guides. NULL = no surgery date given. [PHI-RISK]';
COMMENT ON COLUMN orders.orders.due_at IS 'UTC instant the order is due to the client, from the SLA of its items. NULL = no due date set.';
COMMENT ON COLUMN orders.orders.submitted_at IS 'UTC instant the client submitted the order. NULL = still a draft.';
COMMENT ON COLUMN orders.orders.confirmed_at IS 'UTC instant the order desk accepted the order. NULL = not yet confirmed.';
COMMENT ON COLUMN orders.orders.completed_at IS 'UTC instant every item was completed. NULL = work outstanding.';
COMMENT ON COLUMN orders.orders.closed_at IS 'UTC instant the order was closed administratively. NULL = open.';
COMMENT ON COLUMN orders.orders.closed_by_user_id IS 'Staff user (iam.users) who closed the order. NULL = not closed, closed by the system, or the user was removed.';
COMMENT ON COLUMN orders.orders.cancelled_at IS 'UTC instant the order was cancelled. NULL = not cancelled.';
COMMENT ON COLUMN orders.orders.metadata IS 'Unstructured extra attributes kept from legacy columns with no relational home; never filtered or reported on.';
COMMENT ON COLUMN orders.orders.legacy_id IS 'Orders.ID this row was migrated from. NULL = created in threeddx3.';
COMMENT ON COLUMN orders.orders.legacy_source IS 'Legacy table the row came from (''Orders''). NULL = created in threeddx3.';
COMMENT ON COLUMN orders.orders.legacy_key IS 'Composite legacy key when one id is not enough. NULL = legacy_id alone identifies the row.';
COMMENT ON COLUMN orders.orders.created_at IS 'UTC instant the order was created (legacy Orders creation time for migrated rows). [AUDIT]';
COMMENT ON COLUMN orders.orders.updated_at IS 'UTC instant of the last change; maintained by trg_orders__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN orders.orders.created_by_user_id IS 'iam.users.id of the creator. No FK by design (audit actor). NULL = system, migration or portal self-service without a user. [AUDIT]';
COMMENT ON COLUMN orders.orders.updated_by_user_id IS 'iam.users.id of the last editor. No FK by design (audit actor). NULL = system or migration, or never updated. [AUDIT]';
COMMENT ON COLUMN orders.orders.deleted_at IS 'UTC instant the order was soft-deleted. NULL = live.';
COMMENT ON CONSTRAINT pk_orders ON orders.orders IS 'One row per order.';
COMMENT ON CONSTRAINT uq_orders__uuid ON orders.orders IS 'The public order identifier is globally unique.';
COMMENT ON CONSTRAINT uq_orders__tenant_id__order_number ON orders.orders IS 'An order number identifies one order within a tenant.';
COMMENT ON CONSTRAINT fk_orders__case_id ON orders.orders IS 'Every order belongs to a case; a case cannot be deleted while it has orders.';
COMMENT ON CONSTRAINT fk_orders__project_id ON orders.orders IS 'Optional programme link; removing a project leaves the order without one.';
COMMENT ON CONSTRAINT ck_orders__status ON orders.orders IS 'The order summary status is one of the sixteen client-facing values (kept from v2; detailed states are in workflow).';
COMMENT ON CONSTRAINT ck_orders__priority ON orders.orders IS 'Priority is normal, rush, express or fast_track.';
COMMENT ON CONSTRAINT ck_orders__total_consistent ON orders.orders IS 'The order total always equals subtotal minus discount minus voucher credit plus the manual adjustment. Headers are loaded with all-zero amounts and the item triggers keep them consistent.';
COMMENT ON CONSTRAINT ck_orders__amounts_non_negative ON orders.orders IS 'For orders created in threeddx3 the subtotal, discount, voucher credit and total are never negative (only adjustment_amount may be). Migrated orders (legacy_id set) are exempt because legacy amounts were not validated.';
COMMENT ON INDEX orders.ix_orders__tenant_id__created_at__id IS 'Stable keyset pagination of orders by creation time.';
COMMENT ON INDEX orders.ix_orders__case_id IS 'Orders of a case (case view, split-arch pairing); covers the case FK.';
COMMENT ON INDEX orders.ix_orders__tenant_id__contact_id__created_at IS 'A client''s live orders, newest first (client portal, account page); covers the contact FK.';
COMMENT ON INDEX orders.ix_orders__tenant_id__status__due_at__open IS 'Hot subset: open orders (not completed, cancelled or not indicated) by status and due date for the order desk dashboards.';
COMMENT ON INDEX orders.ix_orders__patient_id IS 'Orders of one patient; covers the patient FK.';
COMMENT ON INDEX orders.ix_orders__scan_center_contact_id IS 'Orders submitted by a scanning centre; covers the FK.';
COMMENT ON INDEX orders.ix_orders__referring_contact_id IS 'Orders by referrer; covers the FK.';
COMMENT ON INDEX orders.ix_orders__sales_rep_user_id__created_at IS 'A sales rep''s orders, newest first (commission and sales reports); covers the FK.';
COMMENT ON INDEX orders.ix_orders__project_id IS 'Orders of a programme; covers the FK.';
COMMENT ON INDEX orders.ix_orders__billing_address_id IS 'Covers the billing-address FK (address deletion check).';
COMMENT ON INDEX orders.ix_orders__shipping_address_id IS 'Covers the shipping-address FK (address deletion check).';
COMMENT ON INDEX orders.ix_orders__closed_by_user_id IS 'Covers the closed-by user FK (user deletion check).';
COMMENT ON INDEX orders.ix_orders__order_reference_trgm IS '"Contains" search on the client''s order reference (order search box).';
COMMENT ON INDEX orders.uq_orders__legacy IS 'Every migrated order is traceable to its Orders row and cannot be loaded twice.';

CREATE TRIGGER trg_orders__touch_updated_at BEFORE UPDATE ON orders.orders
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_orders__touch_updated_at ON orders.orders IS 'Sets updated_at and updated_by_user_id on every update (core.fn_touch_updated_at).';


-- =============================================================================
-- orders.case_pairing_candidates
-- =============================================================================
CREATE TABLE orders.case_pairing_candidates (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id           bigint NOT NULL DEFAULT core.fn_current_tenant(),
    order_a_id          bigint NOT NULL,
    order_b_id          bigint NOT NULL,
    score               numeric(4,3) NOT NULL,
    evidence            jsonb NOT NULL,
    inference_version   varchar(40) NOT NULL,
    decision            varchar(20) NOT NULL DEFAULT 'pending',
    decided_by_user_id  bigint,
    decided_at          timestamptz,
    decision_note       text,
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    created_by_user_id  bigint,
    updated_by_user_id  bigint,
    CONSTRAINT pk_case_pairing_candidates PRIMARY KEY (id),
    CONSTRAINT uq_case_pairing_candidates__order_a_id__order_b_id UNIQUE (order_a_id, order_b_id),
    CONSTRAINT fk_case_pairing_candidates__order_a_id FOREIGN KEY (order_a_id) REFERENCES orders.orders (id) ON DELETE CASCADE,
    CONSTRAINT fk_case_pairing_candidates__order_b_id FOREIGN KEY (order_b_id) REFERENCES orders.orders (id) ON DELETE CASCADE,
    CONSTRAINT ck_case_pairing_candidates__ordered_pair CHECK (order_a_id < order_b_id),
    CONSTRAINT ck_case_pairing_candidates__score_range CHECK (score BETWEEN 0 AND 1),
    CONSTRAINT ck_case_pairing_candidates__decision CHECK (decision IN ('pending', 'accepted', 'rejected')),
    CONSTRAINT ck_case_pairing_candidates__decided_both_or_neither CHECK (num_nonnulls(decided_by_user_id, decided_at) IN (0, 2)),
    CONSTRAINT ck_case_pairing_candidates__decided_when_not_pending CHECK ((decision = 'pending') = (decided_at IS NULL))
);
CREATE INDEX ix_case_pairing_candidates__order_b_id ON orders.case_pairing_candidates (order_b_id);
CREATE INDEX ix_case_pairing_candidates__tenant_id__score__pending ON orders.case_pairing_candidates (tenant_id, score DESC)
    WHERE decision = 'pending';
CREATE INDEX ix_case_pairing_candidates__decided_by_user_id ON orders.case_pairing_candidates (decided_by_user_id)
    WHERE decided_by_user_id IS NOT NULL;

COMMENT ON TABLE orders.case_pairing_candidates IS 'Review list of order pairs that may be one split-arch case but whose evidence was ambiguous (Q3, U8). One row per unordered pair of orders (order_a_id < order_b_id). Written by the ETL pairing step and later by a pairing job; a person accepts (the orders are then moved under one case with pairing_method = ''manual'') or rejects. Unambiguous pairs never appear here; they are linked directly. Contains PII.';
COMMENT ON COLUMN orders.case_pairing_candidates.id IS 'Surrogate key of the candidate pair; system-generated.';
COMMENT ON COLUMN orders.case_pairing_candidates.tenant_id IS 'Tenant that owns both orders (core.tenants); row-level security scope.';
COMMENT ON COLUMN orders.case_pairing_candidates.order_a_id IS 'The pair member with the smaller orders.id.';
COMMENT ON COLUMN orders.case_pairing_candidates.order_b_id IS 'The pair member with the larger orders.id.';
COMMENT ON COLUMN orders.case_pairing_candidates.score IS 'Likelihood 0-1 that the two orders are one split-arch case, from the pairing inference. Calculated.';
COMMENT ON COLUMN orders.case_pairing_candidates.evidence IS 'Inference provenance as JSON: matched signals (patient name, doctor, scanning centre, creation-time gap, arches) and why the pair was not auto-linked. Shown on the review screen; not filtered. May quote patient names. [PHI-RISK]';
COMMENT ON COLUMN orders.case_pairing_candidates.inference_version IS 'Version label of the pairing rules that produced the candidate (e.g. ''etl-v3.0''), so a re-run with new rules can be told apart.';
COMMENT ON COLUMN orders.case_pairing_candidates.decision IS 'Review outcome: ''pending'' = not yet reviewed; ''accepted'' = the reviewer confirmed one case and the orders were merged under one case; ''rejected'' = the orders are separate cases.';
COMMENT ON COLUMN orders.case_pairing_candidates.decided_by_user_id IS 'Staff user (iam.users) who accepted or rejected the pair. NULL = still pending.';
COMMENT ON COLUMN orders.case_pairing_candidates.decided_at IS 'UTC instant of the review decision. NULL = still pending.';
COMMENT ON COLUMN orders.case_pairing_candidates.decision_note IS 'Reviewer''s free-text justification. NULL = none given. [PHI-RISK]';
COMMENT ON COLUMN orders.case_pairing_candidates.created_at IS 'UTC instant the candidate was generated. [AUDIT]';
COMMENT ON COLUMN orders.case_pairing_candidates.updated_at IS 'UTC instant of the last change (the decision); maintained by trg_case_pairing_candidates__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN orders.case_pairing_candidates.created_by_user_id IS 'iam.users.id of the creator. No FK by design (audit actor). NULL = ETL or pairing job. [AUDIT]';
COMMENT ON COLUMN orders.case_pairing_candidates.updated_by_user_id IS 'iam.users.id of the last editor. No FK by design (audit actor). NULL = never updated or system. [AUDIT]';
COMMENT ON CONSTRAINT pk_case_pairing_candidates ON orders.case_pairing_candidates IS 'One row per candidate pair.';
COMMENT ON CONSTRAINT uq_case_pairing_candidates__order_a_id__order_b_id ON orders.case_pairing_candidates IS 'A pair of orders is listed for review at most once.';
COMMENT ON CONSTRAINT fk_case_pairing_candidates__order_a_id ON orders.case_pairing_candidates IS 'The candidate is derived data about the order; it goes with the order.';
COMMENT ON CONSTRAINT fk_case_pairing_candidates__order_b_id ON orders.case_pairing_candidates IS 'The candidate is derived data about the order; it goes with the order.';
COMMENT ON CONSTRAINT ck_case_pairing_candidates__ordered_pair ON orders.case_pairing_candidates IS 'Pairs are stored with the smaller order id first, so (A,B) and (B,A) cannot both exist and an order is never paired with itself.';
COMMENT ON CONSTRAINT ck_case_pairing_candidates__score_range ON orders.case_pairing_candidates IS 'The score is a fraction between 0 and 1.';
COMMENT ON CONSTRAINT ck_case_pairing_candidates__decision ON orders.case_pairing_candidates IS 'Decision is pending, accepted or rejected.';
COMMENT ON CONSTRAINT ck_case_pairing_candidates__decided_both_or_neither ON orders.case_pairing_candidates IS 'Who decided and when are recorded together or not at all.';
COMMENT ON CONSTRAINT ck_case_pairing_candidates__decided_when_not_pending ON orders.case_pairing_candidates IS 'A pending candidate has no decision time; an accepted or rejected one must have it.';
COMMENT ON INDEX orders.ix_case_pairing_candidates__order_b_id IS 'Candidates involving an order as the second member; covers the order_b FK (order_a is covered by the unique pair).';
COMMENT ON INDEX orders.ix_case_pairing_candidates__tenant_id__score__pending IS 'Hot subset: the pending review queue, best candidates first.';
COMMENT ON INDEX orders.ix_case_pairing_candidates__decided_by_user_id IS 'Covers the reviewer FK (user deletion check) and "decisions by reviewer" audits.';

CREATE TRIGGER trg_case_pairing_candidates__touch_updated_at BEFORE UPDATE ON orders.case_pairing_candidates
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_case_pairing_candidates__touch_updated_at ON orders.case_pairing_candidates IS 'Sets updated_at and updated_by_user_id on every update (core.fn_touch_updated_at).';


-- =============================================================================
-- orders.order_items
-- =============================================================================
CREATE TABLE orders.order_items (
    id                     bigint GENERATED BY DEFAULT AS IDENTITY,
    uuid                   uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id              bigint NOT NULL DEFAULT core.fn_current_tenant(),
    order_id               bigint NOT NULL,
    line_number            smallint NOT NULL DEFAULT 1,
    parent_item_id         bigint,
    item_role              varchar(40) NOT NULL DEFAULT 'primary',
    restoration_stage      varchar(20),
    sellable_item_id       bigint NOT NULL,
    item_kind              catalog.item_kind NOT NULL,
    quantity               numeric(10,3) NOT NULL DEFAULT 1,
    status                 varchar(50) NOT NULL DEFAULT 'draft',
    hold_type              varchar(20),
    hold_reason_id         bigint,
    currency_code          core.currency_code NOT NULL,
    unit_price             core.money_amount NOT NULL DEFAULT 0,
    fields_amount          core.money_amount NOT NULL DEFAULT 0,
    discount_amount        core.money_amount NOT NULL DEFAULT 0,
    voucher_amount         core.money_amount NOT NULL DEFAULT 0,
    line_total             core.money_amount NOT NULL DEFAULT 0,
    is_billable            boolean NOT NULL DEFAULT true,
    is_invoiced            boolean NOT NULL DEFAULT false,
    invoice_id             bigint,
    zero_charge_reason_id  bigint,
    zero_charge_note       varchar(255),
    sales_agent_user_id    bigint,
    commission_amount      core.money_amount,
    is_digital             boolean NOT NULL DEFAULT false,
    is_redo                boolean NOT NULL DEFAULT false,
    redo_of_item_id        bigint,
    rush_type_id           bigint,
    service_provider_id    bigint,
    designer_user_id       bigint,
    operator_user_id       bigint,
    reviewer_user_id       bigint,
    shipped_by_user_id     bigint,
    closed_by_user_id      bigint,
    service_notes          text,
    pending_reason         varchar(255),
    due_at                 timestamptz,
    sent_to_production_at  timestamptz,
    design_started_at      timestamptz,
    revised_at             timestamptz,
    completed_at           timestamptz,
    closed_at              timestamptz,
    metadata               jsonb NOT NULL DEFAULT '{}'::jsonb,
    legacy_id              bigint,
    legacy_source          varchar(64),
    legacy_key             varchar(200),
    created_at             timestamptz NOT NULL DEFAULT now(),
    updated_at             timestamptz NOT NULL DEFAULT now(),
    created_by_user_id     bigint,
    updated_by_user_id     bigint,
    deleted_at             timestamptz,
    CONSTRAINT pk_order_items PRIMARY KEY (id),
    CONSTRAINT uq_order_items__uuid UNIQUE (uuid),
    CONSTRAINT uq_order_items__order_id__line_number UNIQUE (order_id, line_number),
    CONSTRAINT fk_order_items__order_id FOREIGN KEY (order_id) REFERENCES orders.orders (id) ON DELETE RESTRICT,
    CONSTRAINT fk_order_items__parent_item_id FOREIGN KEY (parent_item_id) REFERENCES orders.order_items (id) ON DELETE RESTRICT,
    CONSTRAINT fk_order_items__redo_of_item_id FOREIGN KEY (redo_of_item_id) REFERENCES orders.order_items (id) ON DELETE SET NULL,
    CONSTRAINT ck_order_items__status CHECK (status IN ('draft', 'submitted', 'pending_information', 'in_review', 'confirmed',
        'in_design', 'awaiting_approval', 'in_production', 'quality_check', 'ready_to_ship', 'shipped', 'delivered',
        'completed', 'on_hold', 'cancelled', 'not_indicated')),
    CONSTRAINT ck_order_items__item_role CHECK (item_role IN ('primary', 'ismile_suborder', 'refinement',
        'temp_restoration', 'final_restoration', 'addon')),
    CONSTRAINT ck_order_items__restoration_stage CHECK (restoration_stage IS NULL OR restoration_stage IN ('temporary', 'final')),
    CONSTRAINT ck_order_items__role_matches_restoration_stage CHECK (
            (item_role <> 'temp_restoration' OR restoration_stage = 'temporary')
        AND (item_role <> 'final_restoration' OR restoration_stage = 'final')),
    CONSTRAINT ck_order_items__parent_matches_role CHECK (
            (item_role NOT IN ('ismile_suborder', 'refinement') OR parent_item_id IS NOT NULL)
        AND (item_role <> 'primary' OR parent_item_id IS NULL)),
    CONSTRAINT ck_order_items__not_own_parent CHECK (parent_item_id <> id AND redo_of_item_id <> id),
    CONSTRAINT ck_order_items__hold_type CHECK (hold_type IS NULL OR hold_type IN ('customer', 'internal')),
    CONSTRAINT ck_order_items__hold_only_when_on_hold CHECK (hold_type IS NULL OR status = 'on_hold'),
    CONSTRAINT ck_order_items__hold_reason_needs_type CHECK (hold_reason_id IS NULL OR hold_type IS NOT NULL),
    CONSTRAINT ck_order_items__quantity_positive CHECK (quantity > 0),
    CONSTRAINT ck_order_items__total_consistent CHECK (line_total = unit_price * quantity + fields_amount - discount_amount - voucher_amount),
    CONSTRAINT ck_order_items__amounts_non_negative CHECK (legacy_id IS NOT NULL
        OR (unit_price >= 0 AND discount_amount >= 0 AND voucher_amount >= 0 AND line_total >= 0
            AND (commission_amount IS NULL OR commission_amount >= 0))),
    CONSTRAINT ck_order_items__zero_charge_has_reason CHECK (legacy_id IS NOT NULL OR line_total <> 0 OR zero_charge_reason_id IS NOT NULL)
);
CREATE INDEX ix_order_items__tenant_id__created_at__id ON orders.order_items (tenant_id, created_at, id);
CREATE INDEX ix_order_items__tenant_id__status__open ON orders.order_items (tenant_id, status, due_at)
    WHERE status NOT IN ('completed', 'cancelled', 'not_indicated') AND deleted_at IS NULL;
CREATE INDEX ix_order_items__parent_item_id ON orders.order_items (parent_item_id) WHERE parent_item_id IS NOT NULL;
CREATE INDEX ix_order_items__redo_of_item_id ON orders.order_items (redo_of_item_id) WHERE redo_of_item_id IS NOT NULL;
CREATE INDEX ix_order_items__sellable_item_id__status ON orders.order_items (sellable_item_id, status);
CREATE INDEX ix_order_items__invoice_id ON orders.order_items (invoice_id) WHERE invoice_id IS NOT NULL;
CREATE INDEX ix_order_items__tenant_id__created_at__uninvoiced ON orders.order_items (tenant_id, created_at)
    WHERE is_billable AND NOT is_invoiced AND deleted_at IS NULL;
CREATE INDEX ix_order_items__zero_charge_reason_id ON orders.order_items (zero_charge_reason_id) WHERE zero_charge_reason_id IS NOT NULL;
CREATE INDEX ix_order_items__hold_reason_id ON orders.order_items (hold_reason_id) WHERE hold_reason_id IS NOT NULL;
CREATE INDEX ix_order_items__rush_type_id ON orders.order_items (rush_type_id) WHERE rush_type_id IS NOT NULL;
CREATE INDEX ix_order_items__service_provider_id ON orders.order_items (service_provider_id) WHERE service_provider_id IS NOT NULL;
CREATE INDEX ix_order_items__sales_agent_user_id ON orders.order_items (sales_agent_user_id) WHERE sales_agent_user_id IS NOT NULL;
CREATE INDEX ix_order_items__designer_user_id__completed_at ON orders.order_items (designer_user_id, completed_at DESC) WHERE designer_user_id IS NOT NULL;
CREATE INDEX ix_order_items__operator_user_id ON orders.order_items (operator_user_id) WHERE operator_user_id IS NOT NULL;
CREATE INDEX ix_order_items__reviewer_user_id ON orders.order_items (reviewer_user_id) WHERE reviewer_user_id IS NOT NULL;
CREATE INDEX ix_order_items__shipped_by_user_id ON orders.order_items (shipped_by_user_id) WHERE shipped_by_user_id IS NOT NULL;
CREATE INDEX ix_order_items__closed_by_user_id ON orders.order_items (closed_by_user_id) WHERE closed_by_user_id IS NOT NULL;
CREATE UNIQUE INDEX uq_order_items__legacy ON orders.order_items (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE orders.order_items IS 'One service or product line on an order: a surgical guide, treatment plan, report, temporary or final restoration, GFMR, FMP, iSmile sub-order or refinement, software licence, appliance, misc charge. Replaces legacy OrderSG, OrderTP, OrderRestoration, OrderSoftware, OrderMisc, OrderOther, OrderAppliance, OrderSim and SubOrderServices (legacy_source says which). Items form a hierarchy through parent_item_id (iSmile sub-orders under the iSmile item, refinements under the treated item). Execution state lives in workflow.workflow_instances; status here is the client-facing summary. Soft-deleted; price columns are frozen once invoiced (V110). Contains PHI (service_notes).';
COMMENT ON COLUMN orders.order_items.id IS 'Surrogate key of the order item; system-generated.';
COMMENT ON COLUMN orders.order_items.uuid IS 'Public identifier of the order item used by the API, portals and confirmation links.';
COMMENT ON COLUMN orders.order_items.tenant_id IS 'Tenant that owns the item, always the order''s tenant (core.tenants); row-level security scope. Defaults to the session tenant (app.tenant_id) so the ETL column lists of v2 keep working.';
COMMENT ON COLUMN orders.order_items.order_id IS 'Order this line belongs to (orders.orders).';
COMMENT ON COLUMN orders.order_items.line_number IS 'Position of the line on its order, 1-based, unique per order. Assigned by the ETL in legacy order and by the application on creation.';
COMMENT ON COLUMN orders.order_items.parent_item_id IS 'Item this one hangs under: for item_role ''ismile_suborder'' the iSmile treatment item (1-3 sub-orders per iSmile order, legacy Orders.IsmileID -> IsmileOrder -> IsmileSubOrder); for ''refinement'' the item being refined (legacy IsmileOrder.refinementFor); for restorations and add-ons the item they complete when one exists (legacy RestorationID / finalRestorationID). NULL = top-level item (always for ''primary'').';
COMMENT ON COLUMN orders.order_items.item_role IS 'Role of the line within its case: ''primary'' = a top-level service or product ordered on its own; ''ismile_suborder'' = one aligner stage under an iSmile treatment item; ''refinement'' = an iSmile refinement of an earlier treatment; ''temp_restoration'' = the temporary restoration of a restoration pair; ''final_restoration'' = the final restoration of a restoration pair; ''addon'' = an extra service attached to another item (e.g. IOS model auto-created with an SG). Set by the ETL from the legacy hierarchy (Q21) and by the ordering flows.';
COMMENT ON COLUMN orders.order_items.restoration_stage IS 'For restoration items, which stage the line delivers: ''temporary'' = interim prosthesis; ''final'' = definitive prosthesis. Required to match item_role for temp/final restoration roles; may also be set on a primary standalone restoration. NULL = the item is not a restoration.';
COMMENT ON COLUMN orders.order_items.sellable_item_id IS 'Catalogue item sold on this line (catalog.sellable_items); its code includes the order type.';
COMMENT ON COLUMN orders.order_items.item_kind IS 'What the catalogue item is (service, product, license, rental, bundle), copied at order time from the catalogue so later catalogue edits do not change history. [SNAPSHOT]';
COMMENT ON COLUMN orders.order_items.quantity IS 'Number of units ordered (arches, units, licences); positive, up to three decimals.';
COMMENT ON COLUMN orders.order_items.status IS 'Client-facing summary status of the item (same vocabulary as orders.orders.status; detailed state in workflow.workflow_instances): ''draft'' = not submitted; ''submitted'' = received; ''pending_information'' = waiting on the client; ''in_review'' = order-desk check; ''confirmed'' = accepted for work; ''in_design'' = design/planning in progress; ''awaiting_approval'' = waiting for the client''s decision (orders.order_item_decisions); ''in_production'' = being manufactured; ''quality_check'' = in QC; ''ready_to_ship'' = waiting for dispatch; ''shipped'' = dispatched or delivered digitally; ''delivered'' = received; ''completed'' = finished; ''on_hold'' = paused, see hold_type; ''cancelled'' = withdrawn; ''not_indicated'' = rejected as not clinically indicated.';
COMMENT ON COLUMN orders.order_items.hold_type IS 'Why the item is on hold (Final AoX split): ''customer'' = On Hold - Due to Customer (waiting on the client); ''internal'' = On Hold - Internal (3DDX-side reason). Only set while status = ''on_hold''; the hold history is in orders.order_status_history. Requiring a type for every new hold is an application rule, TO CONFIRM as a constraint. NULL = not on hold, or a migrated hold whose type legacy did not record.';
COMMENT ON COLUMN orders.order_items.hold_reason_id IS 'Configured On Hold Reason (core.lookup_values, lookup type for hold reasons) chosen with the hold. NULL = not on hold or no reason chosen.';
COMMENT ON COLUMN orders.order_items.currency_code IS 'Currency of every amount on the line (core.currencies); equals the order currency.';
COMMENT ON COLUMN orders.order_items.unit_price IS 'Price per unit in currency_code at order time, from the pricing engine or legacy cost. [FINANCIAL] [SNAPSHOT]';
COMMENT ON COLUMN orders.order_items.fields_amount IS 'Sum of surcharges from chosen field options (order_item_field_values.charged_amount) in currency_code. Calculated. [FINANCIAL]';
COMMENT ON COLUMN orders.order_items.discount_amount IS 'Discount granted on the line in currency_code. [FINANCIAL]';
COMMENT ON COLUMN orders.order_items.voucher_amount IS 'Voucher credit consumed by the line in currency_code (ledger: vouchers.voucher_transactions.consuming_order_item_id). [FINANCIAL]';
COMMENT ON COLUMN orders.order_items.line_total IS 'Amount charged for the line in currency_code = unit_price x quantity + fields_amount - discount_amount - voucher_amount; maintained by the V110 item-total trigger. A zero total on a line created in threeddx3 needs zero_charge_reason_id. [FINANCIAL]';
COMMENT ON COLUMN orders.order_items.is_billable IS 'true = the line is charged to the client; false = never invoiced (internal remake, free service).';
COMMENT ON COLUMN orders.order_items.is_invoiced IS 'true = the line is on an issued invoice; price, quantity, currency and payer are then frozen (V110 financial lock).';
COMMENT ON COLUMN orders.order_items.invoice_id IS 'Invoice the line was billed on (billing.invoices). NULL = not invoiced yet or not billable.';
COMMENT ON COLUMN orders.order_items.zero_charge_reason_id IS 'Why the line is charged nothing (core.lookup_values, zero-cost reasons such as voucher, redo, other). Required when a line created in threeddx3 has line_total = 0, including lines fully covered by a voucher. NULL = the line has a non-zero total, or is a migrated line whose zero charge legacy did not explain.';
COMMENT ON COLUMN orders.order_items.zero_charge_note IS 'Free-text detail for the zero charge (e.g. "redo of #12345"). User input. NULL = none.';
COMMENT ON COLUMN orders.order_items.sales_agent_user_id IS 'Staff user (iam.users) credited for the sale of this line (legacy SalesAgentId). NULL = no agent credited.';
COMMENT ON COLUMN orders.order_items.commission_amount IS 'Commission due to the sales agent for this line in currency_code. NULL = no commission calculated. [FINANCIAL]';
COMMENT ON COLUMN orders.order_items.is_digital IS 'true = delivered as files only (digital design service); false = a physical product is made or shipped. Selects the workflow definition (with order type and service).';
COMMENT ON COLUMN orders.order_items.is_redo IS 'true = the line is a remake of an earlier item (see redo_of_item_id).';
COMMENT ON COLUMN orders.order_items.redo_of_item_id IS 'Earlier item this line remakes (orders.order_items). NULL = not a redo, or the original is unknown in legacy data.';
COMMENT ON COLUMN orders.order_items.rush_type_id IS 'Rush option chosen for the line (core.lookup_values, rush types). NULL = no rush.';
COMMENT ON COLUMN orders.order_items.service_provider_id IS 'External provider contact (crm.contacts) that performs the work, e.g. a partner lab. NULL = done in house.';
COMMENT ON COLUMN orders.order_items.designer_user_id IS 'Staff designer/planner (iam.users) currently responsible; history of assignments is in orders.order_item_assignments. NULL = not assigned.';
COMMENT ON COLUMN orders.order_items.operator_user_id IS 'Staff operator (iam.users) who produced the item. NULL = not recorded.';
COMMENT ON COLUMN orders.order_items.reviewer_user_id IS 'Staff reviewer / QC (iam.users) of the design. NULL = not reviewed or not recorded.';
COMMENT ON COLUMN orders.order_items.shipped_by_user_id IS 'Staff user (iam.users) who shipped the item. NULL = not shipped or not recorded.';
COMMENT ON COLUMN orders.order_items.closed_by_user_id IS 'Staff user (iam.users) who closed the item. NULL = not closed, closed by the system, or not recorded.';
COMMENT ON COLUMN orders.order_items.service_notes IS 'Free-text clinical/service notes on the line (structured answers are in order_item_field_values); frequently names the patient or describes the treatment. Migrated from legacy Comment columns. NULL = none. [PHI]';
COMMENT ON COLUMN orders.order_items.pending_reason IS 'Text of the reason the item waits on the client (pending_information). NULL = not pending. [PHI-RISK]';
COMMENT ON COLUMN orders.order_items.due_at IS 'UTC instant the item is due, from its workflow SLA. NULL = no due date.';
COMMENT ON COLUMN orders.order_items.sent_to_production_at IS 'UTC instant the item was released to production; for Relu AI plans, the instant the AI plan became ready (charging trigger). NULL = not released.';
COMMENT ON COLUMN orders.order_items.design_started_at IS 'UTC instant design work started. NULL = not started.';
COMMENT ON COLUMN orders.order_items.revised_at IS 'UTC instant of the last design revision. NULL = never revised.';
COMMENT ON COLUMN orders.order_items.completed_at IS 'UTC instant the item was completed. NULL = not completed.';
COMMENT ON COLUMN orders.order_items.closed_at IS 'UTC instant the item was closed. NULL = open.';
COMMENT ON COLUMN orders.order_items.metadata IS 'Unstructured extra attributes kept from legacy columns with no relational home; never filtered or reported on.';
COMMENT ON COLUMN orders.order_items.legacy_id IS 'Legacy row id (SubOrderServices.subOrderID or the OrderXxx/IsmileSubOrder ID). NULL = created in threeddx3; rows created in threeddx3 are bound by the non-negative and zero-charge rules.';
COMMENT ON COLUMN orders.order_items.legacy_source IS 'Legacy table the row came from (SubOrderServices, OrderSG, OrderTP, OrderRestoration, OrderSoftware, OrderMisc, OrderOther, OrderAppliance, OrderSim, IsmileSubOrder). NULL = created in threeddx3.';
COMMENT ON COLUMN orders.order_items.legacy_key IS 'Composite legacy key as the source writes it (v2 V039): SubOrderServices is (subOrderID, serviceID), stored "9:2". NULL = legacy_id alone identifies the row.';
COMMENT ON COLUMN orders.order_items.created_at IS 'UTC instant the item was created (legacy creation time for migrated rows). [AUDIT]';
COMMENT ON COLUMN orders.order_items.updated_at IS 'UTC instant of the last change; maintained by trg_order_items__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN orders.order_items.created_by_user_id IS 'iam.users.id of the creator. No FK by design (audit actor). NULL = system, migration or portal self-service. [AUDIT]';
COMMENT ON COLUMN orders.order_items.updated_by_user_id IS 'iam.users.id of the last editor. No FK by design (audit actor). NULL = system or migration, or never updated. [AUDIT]';
COMMENT ON COLUMN orders.order_items.deleted_at IS 'UTC instant the item was soft-deleted. NULL = live.';
COMMENT ON CONSTRAINT pk_order_items ON orders.order_items IS 'One row per order item.';
COMMENT ON CONSTRAINT uq_order_items__uuid ON orders.order_items IS 'The public item identifier is globally unique.';
COMMENT ON CONSTRAINT uq_order_items__order_id__line_number ON orders.order_items IS 'Line numbers are unique within an order; also serves "items of an order" and covers the order FK.';
COMMENT ON CONSTRAINT fk_order_items__order_id ON orders.order_items IS 'Items are financial records: an order with items cannot be hard-deleted (orders are soft-deleted).';
COMMENT ON CONSTRAINT fk_order_items__parent_item_id ON orders.order_items IS 'A parent item cannot be deleted while sub-orders, refinements or add-ons hang under it.';
COMMENT ON CONSTRAINT fk_order_items__redo_of_item_id ON orders.order_items IS 'Optional link to the remade item; removing the original leaves the redo without the link.';
COMMENT ON CONSTRAINT ck_order_items__status ON orders.order_items IS 'The item summary status is one of the sixteen client-facing values.';
COMMENT ON CONSTRAINT ck_order_items__item_role ON orders.order_items IS 'Item role is primary, ismile_suborder, refinement, temp_restoration, final_restoration or addon.';
COMMENT ON CONSTRAINT ck_order_items__restoration_stage ON orders.order_items IS 'Restoration stage is temporary or final when set.';
COMMENT ON CONSTRAINT ck_order_items__role_matches_restoration_stage ON orders.order_items IS 'A temporary-restoration item has stage temporary; a final-restoration item has stage final.';
COMMENT ON CONSTRAINT ck_order_items__parent_matches_role ON orders.order_items IS 'iSmile sub-orders and refinements always hang under a parent item; a primary item never does.';
COMMENT ON CONSTRAINT ck_order_items__not_own_parent ON orders.order_items IS 'An item cannot be its own parent or remake itself.';
COMMENT ON CONSTRAINT ck_order_items__hold_type ON orders.order_items IS 'Hold type is customer or internal when set.';
COMMENT ON CONSTRAINT ck_order_items__hold_only_when_on_hold ON orders.order_items IS 'A hold type is recorded only while the item is on hold; resuming the item clears it.';
COMMENT ON CONSTRAINT ck_order_items__hold_reason_needs_type ON orders.order_items IS 'A hold reason is only meaningful together with a hold type.';
COMMENT ON CONSTRAINT ck_order_items__quantity_positive ON orders.order_items IS 'Quantity is strictly positive.';
COMMENT ON CONSTRAINT ck_order_items__total_consistent ON orders.order_items IS 'Line total always equals unit price x quantity + field surcharges - discount - voucher credit.';
COMMENT ON CONSTRAINT ck_order_items__amounts_non_negative ON orders.order_items IS 'For lines created in threeddx3, unit price, discount, voucher credit, line total and commission are never negative. Migrated lines (legacy_id set) are exempt because legacy cost columns were unvalidated doubles. Field surcharges may be negative (an option that lowers the price) - TO CONFIRM.';
COMMENT ON CONSTRAINT ck_order_items__zero_charge_has_reason ON orders.order_items IS 'A line created in threeddx3 whose total is zero must say why (zero-cost reason: voucher, redo, other - Final AoX US#32). Migrated lines (legacy_id set) are exempt: legacy never recorded a reason for most free lines, so the rule cannot hold for history.';
COMMENT ON INDEX orders.ix_order_items__tenant_id__created_at__id IS 'Stable keyset pagination of items by creation time.';
COMMENT ON INDEX orders.ix_order_items__tenant_id__status__open IS 'Hot subset: open items (not completed, cancelled or not indicated) by status and due date for the production and design queues.';
COMMENT ON INDEX orders.ix_order_items__parent_item_id IS 'Children of an item (iSmile sub-orders, refinements, add-ons); covers the parent FK.';
COMMENT ON INDEX orders.ix_order_items__redo_of_item_id IS 'Redos of an item; covers the FK.';
COMMENT ON INDEX orders.ix_order_items__sellable_item_id__status IS 'Items of one catalogue service by status (service reports); covers the sellable-item FK.';
COMMENT ON INDEX orders.ix_order_items__invoice_id IS 'Lines of an invoice; covers the invoice FK.';
COMMENT ON INDEX orders.ix_order_items__tenant_id__created_at__uninvoiced IS 'Hot subset: billable lines not yet invoiced (ready-for-charge and invoicing runs).';
COMMENT ON INDEX orders.ix_order_items__zero_charge_reason_id IS 'Zero-charge lines by reason (zero-cost report); covers the FK.';
COMMENT ON INDEX orders.ix_order_items__hold_reason_id IS 'Items on hold by reason (hold reports); covers the FK.';
COMMENT ON INDEX orders.ix_order_items__rush_type_id IS 'Rush items by rush type; covers the FK.';
COMMENT ON INDEX orders.ix_order_items__service_provider_id IS 'Items outsourced to a provider; covers the FK.';
COMMENT ON INDEX orders.ix_order_items__sales_agent_user_id IS 'Lines credited to a sales agent (commission report); covers the FK.';
COMMENT ON INDEX orders.ix_order_items__designer_user_id__completed_at IS 'A designer''s items, latest completion first (designer performance report); covers the FK.';
COMMENT ON INDEX orders.ix_order_items__operator_user_id IS 'Covers the operator FK (user deletion check, operator reports).';
COMMENT ON INDEX orders.ix_order_items__reviewer_user_id IS 'Covers the reviewer FK (user deletion check, QC reports).';
COMMENT ON INDEX orders.ix_order_items__shipped_by_user_id IS 'Covers the shipped-by FK (user deletion check).';
COMMENT ON INDEX orders.ix_order_items__closed_by_user_id IS 'Covers the closed-by FK (user deletion check).';
COMMENT ON INDEX orders.uq_order_items__legacy IS 'Every migrated item is traceable to its legacy row (including the composite SubOrderServices key) and cannot be loaded twice.';

CREATE TRIGGER trg_order_items__touch_updated_at BEFORE UPDATE ON orders.order_items
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_order_items__touch_updated_at ON orders.order_items IS 'Sets updated_at and updated_by_user_id on every update (core.fn_touch_updated_at).';


-- =============================================================================
-- orders.order_item_field_values
-- =============================================================================
CREATE TABLE orders.order_item_field_values (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id           bigint NOT NULL DEFAULT core.fn_current_tenant(),
    order_item_id       bigint NOT NULL,
    field_id            bigint NOT NULL,
    field_option_id     bigint,
    value_text          text,
    value_number        numeric(18,4),
    value_boolean       boolean,
    value_date          date,
    charged_amount      core.money_amount NOT NULL DEFAULT 0,
    legacy_id           bigint,
    legacy_source       varchar(64),
    legacy_key          varchar(200),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    created_by_user_id  bigint,
    updated_by_user_id  bigint,
    CONSTRAINT pk_order_item_field_values PRIMARY KEY (id),
    CONSTRAINT uq_order_item_field_values__item__field__option UNIQUE (order_item_id, field_id, field_option_id),
    CONSTRAINT fk_order_item_field_values__order_item_id FOREIGN KEY (order_item_id) REFERENCES orders.order_items (id) ON DELETE CASCADE
);
CREATE INDEX ix_order_item_field_values__field_id__field_option_id ON orders.order_item_field_values (field_id, field_option_id);
CREATE INDEX ix_order_item_field_values__field_option_id ON orders.order_item_field_values (field_option_id) WHERE field_option_id IS NOT NULL;
CREATE UNIQUE INDEX uq_order_item_field_values__legacy ON orders.order_item_field_values (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE orders.order_item_field_values IS 'Answers given on an order item''s form: one row per field (and per chosen option for multi-select fields), e.g. implant system, printer model, shade. From legacy SubOrderServicesFields. Relational rather than JSON so "which orders selected option X" is an index scan. Child of the order item; edited until the item is locked. May contain PHI in free-text answers.';
COMMENT ON COLUMN orders.order_item_field_values.id IS 'Surrogate key of the answer; system-generated.';
COMMENT ON COLUMN orders.order_item_field_values.tenant_id IS 'Tenant that owns the answer, always the item''s tenant; row-level security scope. Defaults to the session tenant (app.tenant_id) for the ETL.';
COMMENT ON COLUMN orders.order_item_field_values.order_item_id IS 'Order item the answer belongs to (orders.order_items).';
COMMENT ON COLUMN orders.order_item_field_values.field_id IS 'Form field answered (catalog.fields).';
COMMENT ON COLUMN orders.order_item_field_values.field_option_id IS 'Option chosen for a choice field (catalog.field_options). NULL = free-value field (text, number, boolean, date) or legacy answer stored as text.';
COMMENT ON COLUMN orders.order_item_field_values.value_text IS 'Text answer as entered; may name the patient in free-text fields. NULL = field is not a text answer. [PHI-RISK]';
COMMENT ON COLUMN orders.order_item_field_values.value_number IS 'Numeric answer (e.g. sleeve diameter, number of units). NULL = field is not numeric.';
COMMENT ON COLUMN orders.order_item_field_values.value_boolean IS 'Yes/no answer. NULL = field is not a yes/no field.';
COMMENT ON COLUMN orders.order_item_field_values.value_date IS 'Date answer (calendar date). NULL = field is not a date field.';
COMMENT ON COLUMN orders.order_item_field_values.charged_amount IS 'Surcharge this answer adds to the line, in the order item''s currency (orders.order_items.currency_code); summed into order_items.fields_amount. Sign rule TO CONFIRM (legacy ServiceFieldsPrices may hold negative prices). [FINANCIAL] [SNAPSHOT]';
COMMENT ON COLUMN orders.order_item_field_values.legacy_id IS 'SubOrderServicesFields row id. NULL = created in threeddx3.';
COMMENT ON COLUMN orders.order_item_field_values.legacy_source IS 'Legacy table the row came from (''SubOrderServicesFields''). NULL = created in threeddx3.';
COMMENT ON COLUMN orders.order_item_field_values.legacy_key IS 'Composite legacy key when one id is not enough. NULL = legacy_id alone identifies the row.';
COMMENT ON COLUMN orders.order_item_field_values.created_at IS 'UTC instant the answer was recorded. [AUDIT]';
COMMENT ON COLUMN orders.order_item_field_values.updated_at IS 'UTC instant of the last change; maintained by trg_order_item_field_values__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN orders.order_item_field_values.created_by_user_id IS 'iam.users.id of the creator. No FK by design (audit actor). NULL = system, migration or portal. [AUDIT]';
COMMENT ON COLUMN orders.order_item_field_values.updated_by_user_id IS 'iam.users.id of the last editor. No FK by design (audit actor). NULL = never updated or system. [AUDIT]';
COMMENT ON CONSTRAINT pk_order_item_field_values ON orders.order_item_field_values IS 'One row per answer.';
COMMENT ON CONSTRAINT uq_order_item_field_values__item__field__option ON orders.order_item_field_values IS 'An option is chosen at most once per field per item (kept from v2 with NULLS DISTINCT, so free-value answers are not deduplicated by it; the ETL relies on these columns for ON CONFLICT). Also covers the order-item FK.';
COMMENT ON CONSTRAINT fk_order_item_field_values__order_item_id ON orders.order_item_field_values IS 'Answers are true children of the item and go with it.';
COMMENT ON INDEX orders.ix_order_item_field_values__field_id__field_option_id IS '"Which items chose option X of field Y" (service and product reports); covers the field FK.';
COMMENT ON INDEX orders.ix_order_item_field_values__field_option_id IS 'Covers the field-option FK (option deletion check).';
COMMENT ON INDEX orders.uq_order_item_field_values__legacy IS 'Every migrated answer is traceable to its SubOrderServicesFields row and cannot be loaded twice.';

CREATE TRIGGER trg_order_item_field_values__touch_updated_at BEFORE UPDATE ON orders.order_item_field_values
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_order_item_field_values__touch_updated_at ON orders.order_item_field_values IS 'Sets updated_at and updated_by_user_id on every update (core.fn_touch_updated_at).';


-- =============================================================================
-- orders.order_status_history
-- =============================================================================
CREATE TABLE orders.order_status_history (
    id             bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id      bigint NOT NULL DEFAULT core.fn_current_tenant(),
    order_id       bigint NOT NULL,
    order_item_id  bigint,
    from_status    varchar(50),
    to_status      varchar(50) NOT NULL,
    comment        text,
    actor_kind     core.actor_kind NOT NULL DEFAULT 'user',
    actor_user_id  bigint,
    actor_role_id  bigint,
    notified_to    text,
    changed_at     timestamptz NOT NULL DEFAULT now(),
    legacy_id      bigint,
    legacy_source  varchar(64),
    legacy_key     varchar(200),
    CONSTRAINT pk_order_status_history PRIMARY KEY (id),
    CONSTRAINT fk_order_status_history__order_id FOREIGN KEY (order_id) REFERENCES orders.orders (id) ON DELETE RESTRICT,
    CONSTRAINT fk_order_status_history__order_item_id FOREIGN KEY (order_item_id) REFERENCES orders.order_items (id) ON DELETE RESTRICT
);
CREATE INDEX ix_order_status_history__order_id__changed_at ON orders.order_status_history (order_id, changed_at DESC);
CREATE INDEX ix_order_status_history__order_item_id__changed_at ON orders.order_status_history (order_item_id, changed_at DESC) WHERE order_item_id IS NOT NULL;
CREATE INDEX ix_order_status_history__tenant_id__to_status__changed_at ON orders.order_status_history (tenant_id, to_status, changed_at DESC);
CREATE INDEX ix_order_status_history__actor_user_id ON orders.order_status_history (actor_user_id) WHERE actor_user_id IS NOT NULL;
CREATE INDEX ix_order_status_history__actor_role_id ON orders.order_status_history (actor_role_id) WHERE actor_role_id IS NOT NULL;
CREATE UNIQUE INDEX uq_order_status_history__legacy ON orders.order_status_history (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE orders.order_status_history IS 'Append-only log of summary status changes of an order or one of its items: who (user and the role they acted in), when, from what, to what, with the note and who was notified. Merged from legacy OrderHistory, service_status_history and PendingStatusHistory. order_item_id NULL = order-level change. Detailed workflow transitions are in workflow.workflow_history. UPDATE and DELETE are rejected by trigger. Contains PHI-risk free text.';
COMMENT ON COLUMN orders.order_status_history.id IS 'Surrogate key of the entry; system-generated.';
COMMENT ON COLUMN orders.order_status_history.tenant_id IS 'Tenant that owns the order; row-level security scope. Defaults to the session tenant (app.tenant_id) for the ETL.';
COMMENT ON COLUMN orders.order_status_history.order_id IS 'Order whose status changed, or whose item''s status changed (orders.orders).';
COMMENT ON COLUMN orders.order_status_history.order_item_id IS 'Item whose status changed (orders.order_items). NULL = the change was at order level.';
COMMENT ON COLUMN orders.order_status_history.from_status IS 'Summary status before the change (orders.orders.status vocabulary). Not constrained: history keeps what was recorded. NULL = unknown (only legacy service_status_history recorded the previous state) or first status.';
COMMENT ON COLUMN orders.order_status_history.to_status IS 'Summary status after the change (orders.orders.status vocabulary, mapped from legacy codes by etl/status_map.py). Not constrained by CHECK: history keeps what was recorded.';
COMMENT ON COLUMN orders.order_status_history.comment IS 'Note entered with the change (legacy OrderHistory.Comment, pending reason text); may name the patient. NULL = no note. [PHI-RISK]';
COMMENT ON COLUMN orders.order_status_history.actor_kind IS 'Kind of actor: user, system, integration or anonymous (core.actor_kind).';
COMMENT ON COLUMN orders.order_status_history.actor_user_id IS 'Person (iam.users) who made the change. NULL = system, integration or anonymous actor, or a legacy agent that could not be mapped.';
COMMENT ON COLUMN orders.order_status_history.actor_role_id IS 'Role (iam.roles) the person acted in when making the change (requirement: "who, in which role" on every status log; Final AoX GAP-071). Taken from core.fn_current_role_id(). NULL = not a user action, or migrated history (legacy did not record roles).';
COMMENT ON COLUMN orders.order_status_history.notified_to IS 'E-mail addresses notified of the change, as recorded (legacy OrderHistory.MailTo). NULL = nobody notified. [PII]';
COMMENT ON COLUMN orders.order_status_history.changed_at IS 'UTC instant of the status change.';
COMMENT ON COLUMN orders.order_status_history.legacy_id IS 'Row id in the legacy source table. NULL = recorded in threeddx3.';
COMMENT ON COLUMN orders.order_status_history.legacy_source IS 'Legacy table: OrderHistory, service_status_history or PendingStatusHistory. NULL = recorded in threeddx3.';
COMMENT ON COLUMN orders.order_status_history.legacy_key IS 'Composite legacy key when one id is not enough. NULL = legacy_id alone identifies the row.';
COMMENT ON CONSTRAINT pk_order_status_history ON orders.order_status_history IS 'One row per status change.';
COMMENT ON CONSTRAINT fk_order_status_history__order_id ON orders.order_status_history IS 'Status history is retained: an order with history cannot be hard-deleted.';
COMMENT ON CONSTRAINT fk_order_status_history__order_item_id ON orders.order_status_history IS 'Status history is retained: an item with history cannot be hard-deleted.';
COMMENT ON INDEX orders.ix_order_status_history__order_id__changed_at IS 'Timeline of an order, newest first; covers the order FK.';
COMMENT ON INDEX orders.ix_order_status_history__order_item_id__changed_at IS 'Timeline of an item, newest first; covers the item FK.';
COMMENT ON INDEX orders.ix_order_status_history__tenant_id__to_status__changed_at IS '"Which orders entered status X in a period" (turnaround and SLA reports).';
COMMENT ON INDEX orders.ix_order_status_history__actor_user_id IS 'Changes made by one user (staff activity audit); covers the FK.';
COMMENT ON INDEX orders.ix_order_status_history__actor_role_id IS 'Changes made in a role; covers the role FK.';
COMMENT ON INDEX orders.uq_order_status_history__legacy IS 'Every migrated history row is traceable to its legacy row and cannot be loaded twice.';

CREATE TRIGGER trg_order_status_history__append_only BEFORE UPDATE OR DELETE ON orders.order_status_history
    FOR EACH ROW EXECUTE FUNCTION core.fn_reject_mutation();
COMMENT ON TRIGGER trg_order_status_history__append_only ON orders.order_status_history IS 'Rejects UPDATE and DELETE: status history is append-only; corrections are new rows (core.fn_reject_mutation).';


-- =============================================================================
-- orders.order_comments
-- =============================================================================
CREATE TABLE orders.order_comments (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id           bigint NOT NULL DEFAULT core.fn_current_tenant(),
    order_id            bigint NOT NULL,
    order_item_id       bigint,
    body                text NOT NULL,
    visibility          varchar(20) NOT NULL DEFAULT 'internal',
    author_kind         core.actor_kind NOT NULL DEFAULT 'user',
    author_user_id      bigint,
    legacy_id           bigint,
    legacy_source       varchar(64),
    legacy_key          varchar(200),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    updated_by_user_id  bigint,
    deleted_at          timestamptz,
    CONSTRAINT pk_order_comments PRIMARY KEY (id),
    CONSTRAINT fk_order_comments__order_id FOREIGN KEY (order_id) REFERENCES orders.orders (id) ON DELETE CASCADE,
    CONSTRAINT fk_order_comments__order_item_id FOREIGN KEY (order_item_id) REFERENCES orders.order_items (id) ON DELETE CASCADE,
    CONSTRAINT ck_order_comments__visibility CHECK (visibility IN ('internal', 'client', 'public'))
);
CREATE INDEX ix_order_comments__order_id__created_at ON orders.order_comments (order_id, created_at DESC) WHERE deleted_at IS NULL;
CREATE INDEX ix_order_comments__order_item_id ON orders.order_comments (order_item_id) WHERE order_item_id IS NOT NULL;
CREATE INDEX ix_order_comments__author_user_id ON orders.order_comments (author_user_id) WHERE author_user_id IS NOT NULL;
CREATE UNIQUE INDEX uq_order_comments__legacy ON orders.order_comments (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE orders.order_comments IS 'Notes on an order or one of its items (legacy OrderComments): written by staff, clients, the system or an integration, with a visibility that decides who sees them. Soft-deleted with deleted_at. Pre-shipping instructions moved to orders.pre_shipping_instructions in v3. Contains PHI-risk free text.';
COMMENT ON COLUMN orders.order_comments.id IS 'Surrogate key of the comment; system-generated.';
COMMENT ON COLUMN orders.order_comments.tenant_id IS 'Tenant that owns the order; row-level security scope. Defaults to the session tenant (app.tenant_id) for the ETL.';
COMMENT ON COLUMN orders.order_comments.order_id IS 'Order the comment is about (orders.orders).';
COMMENT ON COLUMN orders.order_comments.order_item_id IS 'Item the comment is about (orders.order_items). NULL = about the order as a whole.';
COMMENT ON COLUMN orders.order_comments.body IS 'Comment text; frequently names the patient or describes treatment. [PHI-RISK]';
COMMENT ON COLUMN orders.order_comments.visibility IS 'Who may read it: ''internal'' = 3DDX staff only; ''client'' = staff and the ordering client in the portals; ''public'' = anyone with access to the order, including scanning centre and partners.';
COMMENT ON COLUMN orders.order_comments.author_kind IS 'Kind of author (core.actor_kind): ''user'' = a person; ''system'' = generated by the platform or migration; ''integration'' = an external system; ''anonymous'' = unauthenticated (public link).';
COMMENT ON COLUMN orders.order_comments.author_user_id IS 'Person who wrote it (iam.users), when author_kind is user. Not enforced by a CHECK, because a later user deletion legitimately sets it to NULL. NULL = system, integration or anonymous author, or the user was removed.';
COMMENT ON COLUMN orders.order_comments.legacy_id IS 'OrderComments row id. NULL = written in threeddx3.';
COMMENT ON COLUMN orders.order_comments.legacy_source IS 'Legacy table the row came from. NULL = written in threeddx3.';
COMMENT ON COLUMN orders.order_comments.legacy_key IS 'Composite legacy key when one id is not enough. NULL = legacy_id alone identifies the row.';
COMMENT ON COLUMN orders.order_comments.created_at IS 'UTC instant the comment was written. [AUDIT]';
COMMENT ON COLUMN orders.order_comments.updated_at IS 'UTC instant of the last edit; maintained by trg_order_comments__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN orders.order_comments.updated_by_user_id IS 'iam.users.id of the last editor. No FK by design (audit actor). NULL = never edited or edited by the system. [AUDIT]';
COMMENT ON COLUMN orders.order_comments.deleted_at IS 'UTC instant the comment was soft-deleted. NULL = visible.';
COMMENT ON CONSTRAINT pk_order_comments ON orders.order_comments IS 'One row per comment.';
COMMENT ON CONSTRAINT fk_order_comments__order_id ON orders.order_comments IS 'Comments are true children of the order and go with it.';
COMMENT ON CONSTRAINT fk_order_comments__order_item_id ON orders.order_comments IS 'Item comments are true children of the item and go with it.';
COMMENT ON CONSTRAINT ck_order_comments__visibility ON orders.order_comments IS 'Visibility is internal, client or public.';
COMMENT ON INDEX orders.ix_order_comments__order_id__created_at IS 'Live comments of an order, newest first (order page); covers the order FK.';
COMMENT ON INDEX orders.ix_order_comments__order_item_id IS 'Comments of an item; covers the item FK.';
COMMENT ON INDEX orders.ix_order_comments__author_user_id IS 'Covers the author FK (user deletion check).';
COMMENT ON INDEX orders.uq_order_comments__legacy IS 'Every migrated comment is traceable to its legacy row and cannot be loaded twice.';

CREATE TRIGGER trg_order_comments__touch_updated_at BEFORE UPDATE ON orders.order_comments
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_order_comments__touch_updated_at ON orders.order_comments IS 'Sets updated_at and updated_by_user_id on every update (core.fn_touch_updated_at).';


-- =============================================================================
-- orders.order_locks
-- =============================================================================
CREATE TABLE orders.order_locks (
    id                      bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id               bigint NOT NULL DEFAULT core.fn_current_tenant(),
    order_id                bigint NOT NULL,
    order_item_id           bigint,
    status                  orders.lock_status NOT NULL DEFAULT 'active',
    lock_source             orders.lock_source NOT NULL,
    lock_reason             varchar(255),
    locked_at               timestamptz NOT NULL DEFAULT now(),
    expires_at              timestamptz,
    locked_by_user_id       bigint,
    locked_by_team_id       bigint,
    locked_by_system_job    varchar(100),
    release_source          orders.lock_source,
    released_at             timestamptz,
    released_by_user_id     bigint,
    released_by_system_job  varchar(100),
    legacy_id               bigint,
    legacy_source           varchar(64),
    legacy_key              varchar(200),
    created_at              timestamptz NOT NULL DEFAULT now(),
    updated_at              timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT pk_order_locks PRIMARY KEY (id),
    CONSTRAINT fk_order_locks__order_id FOREIGN KEY (order_id) REFERENCES orders.orders (id) ON DELETE CASCADE,
    CONSTRAINT fk_order_locks__order_item_id FOREIGN KEY (order_item_id) REFERENCES orders.order_items (id) ON DELETE CASCADE,
    CONSTRAINT ck_order_locks__active_has_holder CHECK (status <> 'active'
        OR (lock_source = 'user' AND locked_by_user_id IS NOT NULL)
        OR (lock_source = 'system' AND locked_by_system_job IS NOT NULL)),
    CONSTRAINT ck_order_locks__expires_after_locked CHECK (expires_at IS NULL OR expires_at > locked_at),
    CONSTRAINT ck_order_locks__released_after_locked CHECK (released_at IS NULL OR released_at >= locked_at)
);
CREATE UNIQUE INDEX uq_order_locks__order_id__active ON orders.order_locks (order_id) WHERE status = 'active';
CREATE INDEX ix_order_locks__order_id__locked_at ON orders.order_locks (order_id, locked_at DESC);
CREATE INDEX ix_order_locks__expires_at__active ON orders.order_locks (expires_at) WHERE status = 'active' AND expires_at IS NOT NULL;
CREATE INDEX ix_order_locks__order_item_id ON orders.order_locks (order_item_id) WHERE order_item_id IS NOT NULL;
CREATE INDEX ix_order_locks__locked_by_user_id ON orders.order_locks (locked_by_user_id) WHERE locked_by_user_id IS NOT NULL;
CREATE INDEX ix_order_locks__locked_by_team_id ON orders.order_locks (locked_by_team_id) WHERE locked_by_team_id IS NOT NULL;
CREATE INDEX ix_order_locks__released_by_user_id ON orders.order_locks (released_by_user_id) WHERE released_by_user_id IS NOT NULL;
CREATE UNIQUE INDEX uq_order_locks__legacy ON orders.order_locks (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE orders.order_locks IS 'Edit locks on orders: while a staff member (or a system job such as charging) holds the active lock, edits by anyone else are rejected (V110 trigger). One row per lock episode, from taking it to its release or expiry; at most one active lock per order. Rebuilt from legacy orderLockingHistory events (which never stored the lock itself). Released and expired locks are kept as history.';
COMMENT ON COLUMN orders.order_locks.id IS 'Surrogate key of the lock episode; system-generated.';
COMMENT ON COLUMN orders.order_locks.tenant_id IS 'Tenant that owns the order; row-level security scope. Defaults to the session tenant (app.tenant_id) for the ETL.';
COMMENT ON COLUMN orders.order_locks.order_id IS 'Locked order (orders.orders).';
COMMENT ON COLUMN orders.order_locks.order_item_id IS 'Item the lock was taken for (e.g. a prepper locking one restoration item). NULL = the whole order.';
COMMENT ON COLUMN orders.order_locks.status IS 'Lock state (orders.lock_status): active = held, others'' edits rejected; released = closed by its holder or a supervisor; expired = timed out and released by the system.';
COMMENT ON COLUMN orders.order_locks.lock_source IS 'Who took the lock (orders.lock_source): user = a staff member opened the order for editing; system = a process locked it.';
COMMENT ON COLUMN orders.order_locks.lock_reason IS 'Why the lock was taken (e.g. "charging", "design upload"). NULL = no reason given (normal edit lock).';
COMMENT ON COLUMN orders.order_locks.locked_at IS 'UTC instant the lock was taken.';
COMMENT ON COLUMN orders.order_locks.expires_at IS 'UTC instant the lock lapses if not extended or released. NULL = no automatic expiry (legacy locks, system locks).';
COMMENT ON COLUMN orders.order_locks.locked_by_user_id IS 'Staff user (iam.users) holding the lock when lock_source = user. NULL = system lock, or the user was removed after the lock ended.';
COMMENT ON COLUMN orders.order_locks.locked_by_team_id IS 'Team (iam.teams) on whose behalf the lock was taken. NULL = not taken for a team.';
COMMENT ON COLUMN orders.order_locks.locked_by_system_job IS 'Name of the job holding the lock when lock_source = system (e.g. ''legacy_import'', ''charging''). NULL = user lock.';
COMMENT ON COLUMN orders.order_locks.release_source IS 'Who released it: user or system. NULL = still active.';
COMMENT ON COLUMN orders.order_locks.released_at IS 'UTC instant the lock was released or expired. NULL = still active.';
COMMENT ON COLUMN orders.order_locks.released_by_user_id IS 'Staff user (iam.users) who released it. NULL = still active, released by the system, or the user was removed.';
COMMENT ON COLUMN orders.order_locks.released_by_system_job IS 'Job that released or expired the lock. NULL = still active or released by a user.';
COMMENT ON COLUMN orders.order_locks.legacy_id IS 'orderLockingHistory id of the event that opened the lock. NULL = taken in threeddx3.';
COMMENT ON COLUMN orders.order_locks.legacy_source IS 'Legacy table the episode was rebuilt from (''orderLockingHistory''). NULL = taken in threeddx3.';
COMMENT ON COLUMN orders.order_locks.legacy_key IS 'Composite legacy key when one id is not enough. NULL = legacy_id alone identifies the row.';
COMMENT ON COLUMN orders.order_locks.created_at IS 'UTC instant the row was created. [AUDIT]';
COMMENT ON COLUMN orders.order_locks.updated_at IS 'UTC instant of the last change (release, extension); maintained by trg_order_locks__touch_updated_at. [AUDIT]';
COMMENT ON CONSTRAINT pk_order_locks ON orders.order_locks IS 'One row per lock episode.';
COMMENT ON CONSTRAINT fk_order_locks__order_id ON orders.order_locks IS 'Locks are operational children of the order and go with it.';
COMMENT ON CONSTRAINT fk_order_locks__order_item_id ON orders.order_locks IS 'Item locks are operational children of the item and go with it.';
COMMENT ON CONSTRAINT ck_order_locks__active_has_holder ON orders.order_locks IS 'An active lock names whoever holds it: a user for user locks, a job for system locks. Ended locks are history and may have lost their user to a later deletion.';
COMMENT ON CONSTRAINT ck_order_locks__expires_after_locked ON orders.order_locks IS 'A lock expires after it was taken.';
COMMENT ON CONSTRAINT ck_order_locks__released_after_locked ON orders.order_locks IS 'A lock is released no earlier than it was taken.';
COMMENT ON INDEX orders.uq_order_locks__order_id__active IS 'Hot subset and rule: at most one active lock per order; also the "is this order locked" lookup.';
COMMENT ON INDEX orders.ix_order_locks__order_id__locked_at IS 'Lock history of an order; covers the order FK.';
COMMENT ON INDEX orders.ix_order_locks__expires_at__active IS 'Hot subset: active locks by expiry, for the job that expires stale locks.';
COMMENT ON INDEX orders.ix_order_locks__order_item_id IS 'Locks of an item; covers the item FK.';
COMMENT ON INDEX orders.ix_order_locks__locked_by_user_id IS 'Locks held by a user ("my locks", release on logout); covers the FK.';
COMMENT ON INDEX orders.ix_order_locks__locked_by_team_id IS 'Covers the team FK.';
COMMENT ON INDEX orders.ix_order_locks__released_by_user_id IS 'Covers the releasing-user FK.';
COMMENT ON INDEX orders.uq_order_locks__legacy IS 'Every migrated lock episode is traceable to its opening legacy event and cannot be loaded twice.';

CREATE TRIGGER trg_order_locks__touch_updated_at BEFORE UPDATE ON orders.order_locks
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_order_locks__touch_updated_at ON orders.order_locks IS 'Sets updated_at on every update (core.fn_touch_updated_at).';


-- =============================================================================
-- orders.order_lock_history
-- =============================================================================
CREATE TABLE orders.order_lock_history (
    id                       bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id                bigint NOT NULL DEFAULT core.fn_current_tenant(),
    order_lock_id            bigint NOT NULL,
    action                   varchar(20) NOT NULL,
    source                   orders.lock_source NOT NULL,
    performed_by_user_id     bigint,
    performed_by_system_job  varchar(100),
    reason                   varchar(255),
    legacy_id                bigint,
    legacy_source            varchar(64),
    legacy_key               varchar(200),
    created_at               timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT pk_order_lock_history PRIMARY KEY (id),
    CONSTRAINT fk_order_lock_history__order_lock_id FOREIGN KEY (order_lock_id) REFERENCES orders.order_locks (id) ON DELETE RESTRICT,
    CONSTRAINT ck_order_lock_history__action CHECK (action IN ('locked', 'released', 'force_released', 'expired', 'extended'))
);
CREATE INDEX ix_order_lock_history__order_lock_id ON orders.order_lock_history (order_lock_id);
CREATE INDEX ix_order_lock_history__performed_by_user_id ON orders.order_lock_history (performed_by_user_id) WHERE performed_by_user_id IS NOT NULL;
CREATE UNIQUE INDEX uq_order_lock_history__legacy ON orders.order_lock_history (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE orders.order_lock_history IS 'Append-only event log of each lock episode: taken, extended, released, force-released by a supervisor, expired. One row per event; UPDATE and DELETE rejected by trigger. Migrated events come from legacy orderLockingHistory via the lock they belong to.';
COMMENT ON COLUMN orders.order_lock_history.id IS 'Surrogate key of the event; system-generated.';
COMMENT ON COLUMN orders.order_lock_history.tenant_id IS 'Tenant that owns the order; row-level security scope. Defaults to the session tenant (app.tenant_id) for the ETL.';
COMMENT ON COLUMN orders.order_lock_history.order_lock_id IS 'Lock episode the event belongs to (orders.order_locks).';
COMMENT ON COLUMN orders.order_lock_history.action IS 'What happened: ''locked'' = lock taken; ''released'' = released by its holder; ''force_released'' = released by someone else (supervisor); ''expired'' = timed out; ''extended'' = expiry pushed back.';
COMMENT ON COLUMN orders.order_lock_history.source IS 'Whether a user or a system job performed the action (orders.lock_source).';
COMMENT ON COLUMN orders.order_lock_history.performed_by_user_id IS 'Staff user (iam.users) who performed the action. NULL = performed by a system job.';
COMMENT ON COLUMN orders.order_lock_history.performed_by_system_job IS 'Job that performed the action (''legacy_import'' for migrated events with no agent). NULL = performed by a user.';
COMMENT ON COLUMN orders.order_lock_history.reason IS 'Why, for force releases and extensions. NULL = no reason given.';
COMMENT ON COLUMN orders.order_lock_history.legacy_id IS 'orderLockingHistory id of the event. NULL = recorded in threeddx3 or not carried by the ETL.';
COMMENT ON COLUMN orders.order_lock_history.legacy_source IS 'Legacy table of the event (''orderLockingHistory''). NULL = recorded in threeddx3 or not carried by the ETL.';
COMMENT ON COLUMN orders.order_lock_history.legacy_key IS 'Composite legacy key when one id is not enough. NULL = legacy_id alone identifies the row.';
COMMENT ON COLUMN orders.order_lock_history.created_at IS 'UTC instant the event happened (legacy actionTime for migrated rows).';
COMMENT ON CONSTRAINT pk_order_lock_history ON orders.order_lock_history IS 'One row per lock event.';
COMMENT ON CONSTRAINT fk_order_lock_history__order_lock_id ON orders.order_lock_history IS 'Lock history is retained: a lock with events cannot be deleted (the append-only trigger would reject a cascade anyway).';
COMMENT ON CONSTRAINT ck_order_lock_history__action ON orders.order_lock_history IS 'Action is locked, released, force_released, expired or extended.';
COMMENT ON INDEX orders.ix_order_lock_history__order_lock_id IS 'Events of a lock; covers the lock FK.';
COMMENT ON INDEX orders.ix_order_lock_history__performed_by_user_id IS 'Lock actions by a user (supervisor force-release audit); covers the FK.';
COMMENT ON INDEX orders.uq_order_lock_history__legacy IS 'Every migrated lock event that carries its legacy id is traceable and cannot be loaded twice.';

CREATE TRIGGER trg_order_lock_history__append_only BEFORE UPDATE OR DELETE ON orders.order_lock_history
    FOR EACH ROW EXECUTE FUNCTION core.fn_reject_mutation();
COMMENT ON TRIGGER trg_order_lock_history__append_only ON orders.order_lock_history IS 'Rejects UPDATE and DELETE: lock history is append-only (core.fn_reject_mutation).';


-- =============================================================================
-- orders.shopping_carts
-- =============================================================================
CREATE TABLE orders.shopping_carts (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id           bigint NOT NULL DEFAULT core.fn_current_tenant(),
    contact_id          bigint NOT NULL,
    user_id             bigint,
    status              varchar(20) NOT NULL DEFAULT 'open',
    currency_code       core.currency_code NOT NULL,
    order_id            bigint,
    expires_at          timestamptz,
    legacy_id           bigint,
    legacy_source       varchar(64),
    legacy_key          varchar(200),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    created_by_user_id  bigint,
    updated_by_user_id  bigint,
    CONSTRAINT pk_shopping_carts PRIMARY KEY (id),
    CONSTRAINT fk_shopping_carts__order_id FOREIGN KEY (order_id) REFERENCES orders.orders (id) ON DELETE SET NULL,
    CONSTRAINT ck_shopping_carts__status CHECK (status IN ('open', 'submitted', 'abandoned', 'expired')),
    CONSTRAINT ck_shopping_carts__submitted_has_order CHECK (status <> 'submitted' OR order_id IS NOT NULL OR legacy_id IS NOT NULL)
);
CREATE INDEX ix_shopping_carts__tenant_id__contact_id__status ON orders.shopping_carts (tenant_id, contact_id, status);
CREATE INDEX ix_shopping_carts__order_id ON orders.shopping_carts (order_id) WHERE order_id IS NOT NULL;
CREATE INDEX ix_shopping_carts__user_id ON orders.shopping_carts (user_id) WHERE user_id IS NOT NULL;
CREATE UNIQUE INDEX uq_shopping_carts__legacy ON orders.shopping_carts (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE orders.shopping_carts IS 'Client shopping cart for catalogue products (printers, resins, accessories) before an order is placed; from legacy 3DPrinter_Acc_Shopping_Cart, generalised to any sellable item. One row per cart; a submitted cart points at the order it became. Carts are transient: abandoned and expired carts may be purged.';
COMMENT ON COLUMN orders.shopping_carts.id IS 'Surrogate key of the cart; system-generated.';
COMMENT ON COLUMN orders.shopping_carts.tenant_id IS 'Tenant that owns the cart; row-level security scope.';
COMMENT ON COLUMN orders.shopping_carts.contact_id IS 'Client account the cart belongs to (crm.contacts).';
COMMENT ON COLUMN orders.shopping_carts.user_id IS 'Portal user (iam.users) who filled the cart. NULL = not known (legacy carts) or the user was removed.';
COMMENT ON COLUMN orders.shopping_carts.status IS 'Cart state: ''open'' = being filled; ''submitted'' = turned into an order (order_id); ''abandoned'' = left by the client; ''expired'' = lapsed after expires_at.';
COMMENT ON COLUMN orders.shopping_carts.currency_code IS 'Currency of every price in the cart (core.currencies).';
COMMENT ON COLUMN orders.shopping_carts.order_id IS 'Order the cart was submitted as (orders.orders). NULL = not submitted.';
COMMENT ON COLUMN orders.shopping_carts.expires_at IS 'UTC instant an open cart lapses. NULL = no expiry.';
COMMENT ON COLUMN orders.shopping_carts.legacy_id IS '3DPrinter_Acc_Shopping_Cart row id. NULL = created in threeddx3.';
COMMENT ON COLUMN orders.shopping_carts.legacy_source IS 'Legacy table the row came from. NULL = created in threeddx3.';
COMMENT ON COLUMN orders.shopping_carts.legacy_key IS 'Composite legacy key when one id is not enough. NULL = legacy_id alone identifies the row.';
COMMENT ON COLUMN orders.shopping_carts.created_at IS 'UTC instant the cart was created. [AUDIT]';
COMMENT ON COLUMN orders.shopping_carts.updated_at IS 'UTC instant of the last change; maintained by trg_shopping_carts__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN orders.shopping_carts.created_by_user_id IS 'iam.users.id of the creator. No FK by design (audit actor). NULL = system or migration. [AUDIT]';
COMMENT ON COLUMN orders.shopping_carts.updated_by_user_id IS 'iam.users.id of the last editor. No FK by design (audit actor). NULL = never updated or system. [AUDIT]';
COMMENT ON CONSTRAINT pk_shopping_carts ON orders.shopping_carts IS 'One row per cart.';
COMMENT ON CONSTRAINT fk_shopping_carts__order_id ON orders.shopping_carts IS 'Optional link to the resulting order.';
COMMENT ON CONSTRAINT ck_shopping_carts__status ON orders.shopping_carts IS 'Cart status is open, submitted, abandoned or expired.';
COMMENT ON CONSTRAINT ck_shopping_carts__submitted_has_order ON orders.shopping_carts IS 'A cart submitted in threeddx3 names the order it became; migrated carts are exempt (legacy did not link them).';
COMMENT ON INDEX orders.ix_shopping_carts__tenant_id__contact_id__status IS 'A client''s carts by status (open cart lookup in the portal); covers the contact FK.';
COMMENT ON INDEX orders.ix_shopping_carts__order_id IS 'Covers the order FK.';
COMMENT ON INDEX orders.ix_shopping_carts__user_id IS 'Covers the user FK.';
COMMENT ON INDEX orders.uq_shopping_carts__legacy IS 'Every migrated cart is traceable and cannot be loaded twice.';

CREATE TRIGGER trg_shopping_carts__touch_updated_at BEFORE UPDATE ON orders.shopping_carts
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_shopping_carts__touch_updated_at ON orders.shopping_carts IS 'Sets updated_at and updated_by_user_id on every update (core.fn_touch_updated_at).';


-- =============================================================================
-- orders.shopping_cart_items
-- =============================================================================
CREATE TABLE orders.shopping_cart_items (
    id                bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id         bigint NOT NULL DEFAULT core.fn_current_tenant(),
    cart_id           bigint NOT NULL,
    sellable_item_id  bigint NOT NULL,
    quantity          numeric(10,3) NOT NULL DEFAULT 1,
    unit_price        core.money_amount NOT NULL DEFAULT 0,
    metadata          jsonb NOT NULL DEFAULT '{}'::jsonb,
    legacy_id         bigint,
    legacy_source     varchar(64),
    legacy_key        varchar(200),
    created_at        timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT pk_shopping_cart_items PRIMARY KEY (id),
    CONSTRAINT fk_shopping_cart_items__cart_id FOREIGN KEY (cart_id) REFERENCES orders.shopping_carts (id) ON DELETE CASCADE,
    CONSTRAINT ck_shopping_cart_items__quantity_positive CHECK (quantity > 0),
    CONSTRAINT ck_shopping_cart_items__unit_price_non_negative CHECK (legacy_source IS NOT NULL OR unit_price >= 0)
);
CREATE INDEX ix_shopping_cart_items__cart_id ON orders.shopping_cart_items (cart_id);
CREATE INDEX ix_shopping_cart_items__sellable_item_id ON orders.shopping_cart_items (sellable_item_id);
CREATE UNIQUE INDEX uq_shopping_cart_items__legacy ON orders.shopping_cart_items (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE orders.shopping_cart_items IS 'One product line in a shopping cart: item, quantity and the price shown when it was added. Child of the cart; deleted with it.';
COMMENT ON COLUMN orders.shopping_cart_items.id IS 'Surrogate key of the cart line; system-generated.';
COMMENT ON COLUMN orders.shopping_cart_items.tenant_id IS 'Tenant that owns the cart; row-level security scope. Defaults to the session tenant (app.tenant_id) for the ETL.';
COMMENT ON COLUMN orders.shopping_cart_items.cart_id IS 'Cart the line is in (orders.shopping_carts).';
COMMENT ON COLUMN orders.shopping_cart_items.sellable_item_id IS 'Catalogue item added (catalog.sellable_items).';
COMMENT ON COLUMN orders.shopping_cart_items.quantity IS 'Number of units; positive.';
COMMENT ON COLUMN orders.shopping_cart_items.unit_price IS 'Unit price shown when the item was added, in the cart''s currency (orders.shopping_carts.currency_code). [FINANCIAL] [SNAPSHOT]';
COMMENT ON COLUMN orders.shopping_cart_items.metadata IS 'Extra legacy attributes (legacy item id, description, new/refurbished); never filtered.';
COMMENT ON COLUMN orders.shopping_cart_items.legacy_id IS 'Legacy cart line id. NULL = created in threeddx3 or the legacy line had no own id (the ETL writes legacy_source only).';
COMMENT ON COLUMN orders.shopping_cart_items.legacy_source IS 'Legacy table the line came from. NULL = created in threeddx3.';
COMMENT ON COLUMN orders.shopping_cart_items.legacy_key IS 'Composite legacy key when one id is not enough. NULL = legacy_id alone identifies the row, or no legacy key exists.';
COMMENT ON COLUMN orders.shopping_cart_items.created_at IS 'UTC instant the line was added. [AUDIT]';
COMMENT ON CONSTRAINT pk_shopping_cart_items ON orders.shopping_cart_items IS 'One row per cart line.';
COMMENT ON CONSTRAINT fk_shopping_cart_items__cart_id ON orders.shopping_cart_items IS 'Cart lines are true children of the cart and go with it.';
COMMENT ON CONSTRAINT ck_shopping_cart_items__quantity_positive ON orders.shopping_cart_items IS 'Quantity is strictly positive.';
COMMENT ON CONSTRAINT ck_shopping_cart_items__unit_price_non_negative ON orders.shopping_cart_items IS 'Prices of lines added in threeddx3 are never negative; migrated lines (legacy_source set; the ETL carries no legacy id here) are exempt.';
COMMENT ON INDEX orders.ix_shopping_cart_items__cart_id IS 'Lines of a cart; covers the cart FK.';
COMMENT ON INDEX orders.ix_shopping_cart_items__sellable_item_id IS 'Carts containing a product; covers the sellable-item FK.';
COMMENT ON INDEX orders.uq_shopping_cart_items__legacy IS 'Every migrated cart line with a legacy id is traceable and cannot be loaded twice.';


-- =============================================================================
-- orders.fulfilments
-- =============================================================================
CREATE TABLE orders.fulfilments (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id           bigint NOT NULL DEFAULT core.fn_current_tenant(),
    order_item_id       bigint NOT NULL,
    fulfilment_kind     catalog.fulfilment_kind NOT NULL,
    target_schema       varchar(30) NOT NULL,
    target_table        varchar(60) NOT NULL,
    target_id           bigint,
    status              varchar(30) NOT NULL DEFAULT 'pending',
    started_at          timestamptz,
    completed_at        timestamptz,
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    created_by_user_id  bigint,
    updated_by_user_id  bigint,
    CONSTRAINT pk_fulfilments PRIMARY KEY (id),
    CONSTRAINT fk_fulfilments__order_item_id FOREIGN KEY (order_item_id) REFERENCES orders.order_items (id) ON DELETE RESTRICT,
    CONSTRAINT ck_fulfilments__status CHECK (status IN ('pending', 'in_progress', 'completed', 'failed', 'cancelled')),
    CONSTRAINT ck_fulfilments__completed_after_started CHECK (completed_at IS NULL OR started_at IS NULL OR completed_at >= started_at)
);
CREATE INDEX ix_fulfilments__order_item_id__status ON orders.fulfilments (order_item_id, status);

COMMENT ON TABLE orders.fulfilments IS 'Routes an order item to the domain that executes it (production job, inventory issue, licence, rental) so orders carry no per-domain execution columns. One row per routing of an item; target_schema/target_table/target_id name the executing record (polymorphic, so no FK). Not migrated from legacy; created by the order-placement flow.';
COMMENT ON COLUMN orders.fulfilments.id IS 'Surrogate key of the routing; system-generated.';
COMMENT ON COLUMN orders.fulfilments.tenant_id IS 'Tenant that owns the item; row-level security scope. Defaults to the session tenant (app.tenant_id).';
COMMENT ON COLUMN orders.fulfilments.order_item_id IS 'Item being fulfilled (orders.order_items).';
COMMENT ON COLUMN orders.fulfilments.fulfilment_kind IS 'How the item is delivered (catalog.fulfilment_kind): production, inventory, licensing, rental, manual, none.';
COMMENT ON COLUMN orders.fulfilments.target_schema IS 'Schema of the executing record (e.g. ''production'', ''inventory'').';
COMMENT ON COLUMN orders.fulfilments.target_table IS 'Table of the executing record (e.g. ''production_jobs'', ''reservations'').';
COMMENT ON COLUMN orders.fulfilments.target_id IS 'Id of the executing record in target_schema.target_table; polymorphic, checked by the application. NULL = the executing record has not been created yet.';
COMMENT ON COLUMN orders.fulfilments.status IS 'Routing state: ''pending'' = waiting to start; ''in_progress'' = executing; ''completed'' = delivered; ''failed'' = execution failed, needs attention; ''cancelled'' = no longer needed.';
COMMENT ON COLUMN orders.fulfilments.started_at IS 'UTC instant execution started. NULL = not started.';
COMMENT ON COLUMN orders.fulfilments.completed_at IS 'UTC instant execution completed. NULL = not completed.';
COMMENT ON COLUMN orders.fulfilments.created_at IS 'UTC instant the routing was created. [AUDIT]';
COMMENT ON COLUMN orders.fulfilments.updated_at IS 'UTC instant of the last change; maintained by trg_fulfilments__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN orders.fulfilments.created_by_user_id IS 'iam.users.id of the creator. No FK by design (audit actor). NULL = system. [AUDIT]';
COMMENT ON COLUMN orders.fulfilments.updated_by_user_id IS 'iam.users.id of the last editor. No FK by design (audit actor). NULL = never updated or system. [AUDIT]';
COMMENT ON CONSTRAINT pk_fulfilments ON orders.fulfilments IS 'One row per routing.';
COMMENT ON CONSTRAINT fk_fulfilments__order_item_id ON orders.fulfilments IS 'Fulfilment records are execution history of the item; an item with fulfilments cannot be hard-deleted.';
COMMENT ON CONSTRAINT ck_fulfilments__status ON orders.fulfilments IS 'Status is pending, in_progress, completed, failed or cancelled.';
COMMENT ON CONSTRAINT ck_fulfilments__completed_after_started ON orders.fulfilments IS 'Execution completes no earlier than it started.';
COMMENT ON INDEX orders.ix_fulfilments__order_item_id__status IS 'Routings of an item by status; covers the item FK.';

CREATE TRIGGER trg_fulfilments__touch_updated_at BEFORE UPDATE ON orders.fulfilments
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_fulfilments__touch_updated_at ON orders.fulfilments IS 'Sets updated_at and updated_by_user_id on every update (core.fn_touch_updated_at).';


-- =============================================================================
-- orders.download_tracking
-- =============================================================================
CREATE TABLE orders.download_tracking (
    id             bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id      bigint NOT NULL DEFAULT core.fn_current_tenant(),
    order_id       bigint,
    order_item_id  bigint,
    document_id    bigint,
    user_id        bigint,
    ip_address     inet,
    downloaded_at  timestamptz NOT NULL DEFAULT now(),
    legacy_id      bigint,
    legacy_source  varchar(64),
    legacy_key     varchar(200),
    CONSTRAINT pk_download_tracking PRIMARY KEY (id),
    CONSTRAINT fk_download_tracking__order_id FOREIGN KEY (order_id) REFERENCES orders.orders (id) ON DELETE RESTRICT,
    CONSTRAINT fk_download_tracking__order_item_id FOREIGN KEY (order_item_id) REFERENCES orders.order_items (id) ON DELETE RESTRICT,
    CONSTRAINT ck_download_tracking__has_subject CHECK (num_nonnulls(order_id, order_item_id, document_id) >= 1)
);
CREATE INDEX ix_download_tracking__order_id ON orders.download_tracking (order_id) WHERE order_id IS NOT NULL;
CREATE INDEX ix_download_tracking__order_item_id ON orders.download_tracking (order_item_id) WHERE order_item_id IS NOT NULL;
CREATE INDEX ix_download_tracking__document_id ON orders.download_tracking (document_id) WHERE document_id IS NOT NULL;
CREATE INDEX ix_download_tracking__user_id ON orders.download_tracking (user_id) WHERE user_id IS NOT NULL;
CREATE INDEX ix_download_tracking__tenant_id__downloaded_at__id ON orders.download_tracking (tenant_id, downloaded_at, id);
CREATE UNIQUE INDEX uq_download_tracking__legacy ON orders.download_tracking (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE orders.download_tracking IS 'Append-only log of order files downloaded by staff or clients (legacy downloaded_orders): what was downloaded, by whom, from where, when. Used for "was the design downloaded" checks and as an access trail for patient files. UPDATE and DELETE rejected by trigger.';
COMMENT ON COLUMN orders.download_tracking.id IS 'Surrogate key of the download event; system-generated.';
COMMENT ON COLUMN orders.download_tracking.tenant_id IS 'Tenant that owns the order; row-level security scope. Defaults to the session tenant (app.tenant_id) for the ETL.';
COMMENT ON COLUMN orders.download_tracking.order_id IS 'Order whose files were downloaded (orders.orders). NULL = download of a document not tied to an order record.';
COMMENT ON COLUMN orders.download_tracking.order_item_id IS 'Item whose files were downloaded (orders.order_items). NULL = order-level download or item unknown (legacy).';
COMMENT ON COLUMN orders.download_tracking.document_id IS 'Exact file downloaded (docs.documents). NULL = not recorded (legacy rows record only the order).';
COMMENT ON COLUMN orders.download_tracking.user_id IS 'Person (iam.users) who downloaded. NULL = not recorded (legacy never stored who) or anonymous link download.';
COMMENT ON COLUMN orders.download_tracking.ip_address IS 'Client IP address of the download request. NULL = not recorded (legacy). [PII]';
COMMENT ON COLUMN orders.download_tracking.downloaded_at IS 'UTC instant of the download.';
COMMENT ON COLUMN orders.download_tracking.legacy_id IS 'downloaded_orders.Id. NULL = recorded in threeddx3.';
COMMENT ON COLUMN orders.download_tracking.legacy_source IS 'Legacy table (''downloaded_orders''). NULL = recorded in threeddx3.';
COMMENT ON COLUMN orders.download_tracking.legacy_key IS 'Composite legacy key when one id is not enough. NULL = legacy_id alone identifies the row.';
COMMENT ON CONSTRAINT pk_download_tracking ON orders.download_tracking IS 'One row per download event.';
COMMENT ON CONSTRAINT fk_download_tracking__order_id ON orders.download_tracking IS 'The download log is retained access history: an order with downloads cannot be hard-deleted.';
COMMENT ON CONSTRAINT fk_download_tracking__order_item_id ON orders.download_tracking IS 'The download log is retained access history: an item with downloads cannot be hard-deleted.';
COMMENT ON CONSTRAINT ck_download_tracking__has_subject ON orders.download_tracking IS 'A download event names at least the order, the item or the document downloaded.';
COMMENT ON INDEX orders.ix_download_tracking__order_id IS 'Downloads of an order; covers the order FK.';
COMMENT ON INDEX orders.ix_download_tracking__order_item_id IS 'Downloads of an item; covers the item FK.';
COMMENT ON INDEX orders.ix_download_tracking__document_id IS 'Downloads of a file; covers the document FK.';
COMMENT ON INDEX orders.ix_download_tracking__user_id IS 'Downloads by a user (access audit); covers the user FK.';
COMMENT ON INDEX orders.ix_download_tracking__tenant_id__downloaded_at__id IS 'Stable keyset pagination of the download log by time.';
COMMENT ON INDEX orders.uq_download_tracking__legacy IS 'Every migrated download is traceable and cannot be loaded twice.';

CREATE TRIGGER trg_download_tracking__append_only BEFORE UPDATE OR DELETE ON orders.download_tracking
    FOR EACH ROW EXECUTE FUNCTION core.fn_reject_mutation();
COMMENT ON TRIGGER trg_download_tracking__append_only ON orders.download_tracking IS 'Rejects UPDATE and DELETE: the download log is append-only (core.fn_reject_mutation).';


-- =============================================================================
-- orders.confirmation_links
-- =============================================================================
CREATE TABLE orders.confirmation_links (
    id                    bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id             bigint NOT NULL DEFAULT core.fn_current_tenant(),
    uuid                  uuid NOT NULL DEFAULT gen_random_uuid(),
    order_item_id         bigint NOT NULL,
    workflow_state_id     bigint,
    purpose               varchar(40) NOT NULL,
    token_hash            core.sha256_hex NOT NULL,
    recipient_contact_id  bigint,
    recipient_email       core.email_address,
    expires_at            timestamptz NOT NULL,
    used_at               timestamptz,
    invalidated_at        timestamptz,
    invalidated_reason    varchar(40),
    created_at            timestamptz NOT NULL DEFAULT now(),
    updated_at            timestamptz NOT NULL DEFAULT now(),
    created_by_user_id    bigint,
    updated_by_user_id    bigint,
    CONSTRAINT pk_confirmation_links PRIMARY KEY (id),
    CONSTRAINT uq_confirmation_links__uuid UNIQUE (uuid),
    CONSTRAINT uq_confirmation_links__token_hash UNIQUE (token_hash),
    CONSTRAINT fk_confirmation_links__order_item_id FOREIGN KEY (order_item_id) REFERENCES orders.order_items (id) ON DELETE RESTRICT,
    CONSTRAINT ck_confirmation_links__purpose CHECK (purpose IN ('design_confirmation', 'try_in_confirmation',
        'ti_bar_confirmation', 'zirconia_confirmation', 'stl_confirmation', 'shipment_notification',
        'ismile_doctor_confirmation')),
    CONSTRAINT ck_confirmation_links__expires_after_created CHECK (expires_at > created_at),
    CONSTRAINT ck_confirmation_links__used_after_created CHECK (used_at IS NULL OR used_at >= created_at),
    CONSTRAINT ck_confirmation_links__invalidated_both_or_neither CHECK (num_nonnulls(invalidated_at, invalidated_reason) IN (0, 2)),
    CONSTRAINT ck_confirmation_links__invalidated_reason CHECK (invalidated_reason IS NULL
        OR invalidated_reason IN ('status_changed', 'superseded', 'revoked', 'order_cancelled')),
    CONSTRAINT ck_confirmation_links__single_end CHECK (num_nonnulls(used_at, invalidated_at) <= 1)
);
CREATE INDEX ix_confirmation_links__order_item_id ON orders.confirmation_links (order_item_id);
CREATE INDEX ix_confirmation_links__expires_at__open ON orders.confirmation_links (expires_at)
    WHERE used_at IS NULL AND invalidated_at IS NULL;
CREATE INDEX ix_confirmation_links__recipient_contact_id ON orders.confirmation_links (recipient_contact_id) WHERE recipient_contact_id IS NOT NULL;
CREATE INDEX ix_confirmation_links__workflow_state_id ON orders.confirmation_links (workflow_state_id) WHERE workflow_state_id IS NOT NULL;

COMMENT ON TABLE orders.confirmation_links IS 'Single-use secure links e-mailed to a doctor so they can confirm or request amendments without logging in (Final AoX, FMP, iSmile; digest 03 X4). One row per issued link; only the SHA-256 of the token is stored. A link ends once: used (a decision was recorded, orders.order_item_decisions.confirmation_link_id) or invalidated (status changed manually or automatically, superseded, revoked). Shipment-notification links live 6 months; others expire at the next status change. Contains PII.';
COMMENT ON COLUMN orders.confirmation_links.id IS 'Surrogate key of the link; system-generated.';
COMMENT ON COLUMN orders.confirmation_links.tenant_id IS 'Tenant that owns the item; row-level security scope.';
COMMENT ON COLUMN orders.confirmation_links.uuid IS 'Public identifier of the link record (not the token) for support and audit screens.';
COMMENT ON COLUMN orders.confirmation_links.order_item_id IS 'Order item the link asks a decision about (orders.order_items).';
COMMENT ON COLUMN orders.confirmation_links.workflow_state_id IS 'Approval-gate state the link was issued at (workflow.workflow_states); a status change away from it invalidates the link. NULL = not tied to a gate (shipment notification).';
COMMENT ON COLUMN orders.confirmation_links.purpose IS 'What the link confirms: ''design_confirmation'' = doctor approves a design (AoX Design QC email, FMP); ''try_in_confirmation'' = try-in approve / redo / proceed; ''ti_bar_confirmation'' = Ti bar approval; ''zirconia_confirmation'' = Zirconia product confirmation; ''stl_confirmation'' = design STL approval; ''shipment_notification'' = post-ship confirmation link in the shipment email (6-month life); ''ismile_doctor_confirmation'' = iSmile treatment plan confirmation. List TO CONFIRM against the final email catalogue.';
COMMENT ON COLUMN orders.confirmation_links.token_hash IS 'SHA-256 (hex) of the random token in the link URL; the token itself is never stored. Looked up on every link click. [SECRET-REF]';
COMMENT ON COLUMN orders.confirmation_links.recipient_contact_id IS 'Client contact the link was sent to (crm.contacts). NULL = sent to an address that is not a contact (e.g. a scanning-centre mailbox).';
COMMENT ON COLUMN orders.confirmation_links.recipient_email IS 'E-mail address the link was sent to, as sent. NULL = delivered in the Connect portal only, not by e-mail. [PII] [SNAPSHOT]';
COMMENT ON COLUMN orders.confirmation_links.expires_at IS 'UTC instant after which the link no longer works (shipment notifications: 6 months after issue).';
COMMENT ON COLUMN orders.confirmation_links.used_at IS 'UTC instant the link was used to record a decision; it stops working immediately. NULL = not used.';
COMMENT ON COLUMN orders.confirmation_links.invalidated_at IS 'UTC instant the link was invalidated before use. NULL = not invalidated.';
COMMENT ON COLUMN orders.confirmation_links.invalidated_reason IS 'Why it was invalidated: ''status_changed'' = the item left the gate state (manual or automatic status change); ''superseded'' = a newer link was sent for the same purpose; ''revoked'' = cancelled by staff; ''order_cancelled'' = the order or item was cancelled. NULL = not invalidated.';
COMMENT ON COLUMN orders.confirmation_links.created_at IS 'UTC instant the link was issued. [AUDIT]';
COMMENT ON COLUMN orders.confirmation_links.updated_at IS 'UTC instant of the last change (use or invalidation); maintained by trg_confirmation_links__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN orders.confirmation_links.created_by_user_id IS 'iam.users.id of the staff member whose action issued the link (e.g. Design QC). No FK by design (audit actor). NULL = issued by the system. [AUDIT]';
COMMENT ON COLUMN orders.confirmation_links.updated_by_user_id IS 'iam.users.id of the last editor. No FK by design (audit actor). NULL = system or anonymous link use. [AUDIT]';
COMMENT ON CONSTRAINT pk_confirmation_links ON orders.confirmation_links IS 'One row per issued link.';
COMMENT ON CONSTRAINT uq_confirmation_links__uuid ON orders.confirmation_links IS 'The public link record identifier is globally unique.';
COMMENT ON CONSTRAINT uq_confirmation_links__token_hash ON orders.confirmation_links IS 'A token resolves to exactly one link.';
COMMENT ON CONSTRAINT fk_confirmation_links__order_item_id ON orders.confirmation_links IS 'Links are evidence of what the doctor was asked; an item with links cannot be hard-deleted.';
COMMENT ON CONSTRAINT ck_confirmation_links__purpose ON orders.confirmation_links IS 'Purpose is one of the known confirmation e-mails.';
COMMENT ON CONSTRAINT ck_confirmation_links__expires_after_created ON orders.confirmation_links IS 'A link expires after it was issued.';
COMMENT ON CONSTRAINT ck_confirmation_links__used_after_created ON orders.confirmation_links IS 'A link is used no earlier than it was issued.';
COMMENT ON CONSTRAINT ck_confirmation_links__invalidated_both_or_neither ON orders.confirmation_links IS 'An invalidation always records its reason, and a reason only exists with an invalidation time.';
COMMENT ON CONSTRAINT ck_confirmation_links__invalidated_reason ON orders.confirmation_links IS 'Invalidation reason is status_changed, superseded, revoked or order_cancelled.';
COMMENT ON CONSTRAINT ck_confirmation_links__single_end ON orders.confirmation_links IS 'A link ends once: it is either used or invalidated, never both.';
COMMENT ON INDEX orders.ix_confirmation_links__order_item_id IS 'Links of an item (invalidate all open links on a status change); covers the item FK.';
COMMENT ON INDEX orders.ix_confirmation_links__expires_at__open IS 'Hot subset: open links by expiry (expiry sweep, reminder emails).';
COMMENT ON INDEX orders.ix_confirmation_links__recipient_contact_id IS 'Links sent to a contact; covers the contact FK.';
COMMENT ON INDEX orders.ix_confirmation_links__workflow_state_id IS 'Covers the workflow-state FK.';

CREATE TRIGGER trg_confirmation_links__touch_updated_at BEFORE UPDATE ON orders.confirmation_links
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_confirmation_links__touch_updated_at ON orders.confirmation_links IS 'Sets updated_at and updated_by_user_id on every update (core.fn_touch_updated_at).';


-- =============================================================================
-- orders.order_item_decisions
-- =============================================================================
CREATE TABLE orders.order_item_decisions (
    id                    bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id             bigint NOT NULL DEFAULT core.fn_current_tenant(),
    uuid                  uuid NOT NULL DEFAULT gen_random_uuid(),
    order_item_id         bigint NOT NULL,
    workflow_state_id     bigint,
    decision_kind         varchar(40) NOT NULL,
    channel               varchar(20) NOT NULL,
    notes                 text,
    actor_user_id         bigint,
    actor_contact_id      bigint,
    confirmation_link_id  bigint,
    subject_document_id   bigint,
    supersedes_id         bigint,
    idempotency_key       varchar(100) NOT NULL,
    content_hash          core.sha256_hex,
    decided_at            timestamptz NOT NULL DEFAULT now(),
    created_at            timestamptz NOT NULL DEFAULT now(),
    created_by_user_id    bigint,
    CONSTRAINT pk_order_item_decisions PRIMARY KEY (id),
    CONSTRAINT uq_order_item_decisions__uuid UNIQUE (uuid),
    CONSTRAINT uq_order_item_decisions__tenant_id__idempotency_key UNIQUE (tenant_id, idempotency_key),
    CONSTRAINT fk_order_item_decisions__order_item_id FOREIGN KEY (order_item_id) REFERENCES orders.order_items (id) ON DELETE RESTRICT,
    CONSTRAINT fk_order_item_decisions__confirmation_link_id FOREIGN KEY (confirmation_link_id) REFERENCES orders.confirmation_links (id) ON DELETE RESTRICT,
    CONSTRAINT fk_order_item_decisions__supersedes_id FOREIGN KEY (supersedes_id) REFERENCES orders.order_item_decisions (id) ON DELETE RESTRICT,
    CONSTRAINT ck_order_item_decisions__decision_kind CHECK (decision_kind IN ('confirmed', 'amendment_requested',
        'redo_try_in', 'proceed_with_minor_adjustments', 'post_ship_adjustment_requested',
        'ft_session_requested', 'proceed_guide_fabrication')),
    CONSTRAINT ck_order_item_decisions__channel CHECK (channel IN ('email_link', 'connect', 'cp', 'verbal', 'api')),
    CONSTRAINT ck_order_item_decisions__one_actor CHECK (num_nonnulls(actor_user_id, actor_contact_id) = 1),
    CONSTRAINT ck_order_item_decisions__link_iff_email_channel CHECK ((channel = 'email_link') = (confirmation_link_id IS NOT NULL)),
    CONSTRAINT ck_order_item_decisions__amendment_has_notes CHECK (decision_kind <> 'amendment_requested'
        OR (notes IS NOT NULL AND btrim(notes) <> '')),
    CONSTRAINT ck_order_item_decisions__not_self_superseding CHECK (supersedes_id <> id)
);
CREATE INDEX ix_order_item_decisions__order_item_id__decided_at ON orders.order_item_decisions (order_item_id, decided_at DESC);
CREATE INDEX ix_order_item_decisions__tenant_id__created_at__id ON orders.order_item_decisions (tenant_id, created_at, id);
CREATE UNIQUE INDEX uq_order_item_decisions__confirmation_link_id ON orders.order_item_decisions (confirmation_link_id) WHERE confirmation_link_id IS NOT NULL;
CREATE UNIQUE INDEX uq_order_item_decisions__supersedes_id ON orders.order_item_decisions (supersedes_id) WHERE supersedes_id IS NOT NULL;
CREATE INDEX ix_order_item_decisions__actor_user_id ON orders.order_item_decisions (actor_user_id) WHERE actor_user_id IS NOT NULL;
CREATE INDEX ix_order_item_decisions__actor_contact_id ON orders.order_item_decisions (actor_contact_id) WHERE actor_contact_id IS NOT NULL;
CREATE INDEX ix_order_item_decisions__subject_document_id ON orders.order_item_decisions (subject_document_id) WHERE subject_document_id IS NOT NULL;
CREATE INDEX ix_order_item_decisions__workflow_state_id ON orders.order_item_decisions (workflow_state_id) WHERE workflow_state_id IS NOT NULL;

COMMENT ON TABLE orders.order_item_decisions IS 'Append-only record of client decisions at approval gates (digest 03 X4): design/try-in/Ti bar/Zirconia confirmation or amendment request (Final AoX, FMP), redo try-in, post-ship adjustment, Relu AI plan actions (FT session, amendment, proceed with guide fabrication), iSmile doctor confirmation. One row per decision with who (doctor contact or staff user), how (channel), when, notes and the exact file approved. A regulated record (21 CFR Part 11 design approval, V3_DESIGN C6): rows are never updated or deleted; a correction is a new row with supersedes_id. Idempotent: the same idempotency key cannot record twice. Contains PHI-risk free text.';
COMMENT ON COLUMN orders.order_item_decisions.id IS 'Surrogate key of the decision; system-generated.';
COMMENT ON COLUMN orders.order_item_decisions.tenant_id IS 'Tenant that owns the item; row-level security scope.';
COMMENT ON COLUMN orders.order_item_decisions.uuid IS 'Public identifier of the decision (API responses, signature references).';
COMMENT ON COLUMN orders.order_item_decisions.order_item_id IS 'Order item decided on (orders.order_items).';
COMMENT ON COLUMN orders.order_item_decisions.workflow_state_id IS 'Gate state the item was in when the decision was made (workflow.workflow_states, is_approval_gate). NULL = decision not taken at a workflow gate (e.g. Relu clinic actions on the AI plan dashboard).';
COMMENT ON COLUMN orders.order_item_decisions.decision_kind IS 'What was decided: ''confirmed'' = client approves the design/try-in/product/plan as sent; ''amendment_requested'' = client asks for changes (notes required); ''redo_try_in'' = try-in must be remade (AoX); ''proceed_with_minor_adjustments'' = proceed to Ti bar/Zirconia with minor adjustments (AoX); ''post_ship_adjustment_requested'' = adjustment requested after shipping, item returns to QC (AoX); ''ft_session_requested'' = fine-tuning session booked on the Relu AI plan; ''proceed_guide_fabrication'' = proceed with guide fabrication from the Relu AI plan. List TO CONFIRM as further gates are specified.';
COMMENT ON COLUMN orders.order_item_decisions.channel IS 'How the decision reached 3DDX: ''email_link'' = confirmation link in an e-mail (confirmation_link_id); ''connect'' = Connect portal popup or button; ''cp'' = entered in CP by staff; ''verbal'' = told to staff by phone or in person and recorded by them; ''api'' = an integration partner.';
COMMENT ON COLUMN orders.order_item_decisions.notes IS 'Client''s notes with the decision (optional for confirmations, required for amendment requests; Relu caps amendment text at 2000 characters in the UI). Printed in internal history; may name the patient. NULL = no notes. [PHI-RISK]';
COMMENT ON COLUMN orders.order_item_decisions.actor_user_id IS 'Person (iam.users) who decided, when the decision maker has a login (portal user, or staff deciding internally). NULL = the decider is identified by actor_contact_id instead.';
COMMENT ON COLUMN orders.order_item_decisions.actor_contact_id IS 'Client contact (crm.contacts) who decided without a login (e-mail link, verbal decision recorded by staff in created_by_user_id). NULL = the decider is identified by actor_user_id instead.';
COMMENT ON COLUMN orders.order_item_decisions.confirmation_link_id IS 'Confirmation link used (orders.confirmation_links); each link records at most one decision. NULL = decision not made through an e-mail link.';
COMMENT ON COLUMN orders.order_item_decisions.subject_document_id IS 'Exact file version approved or rejected (docs.documents: HTML review, design STL). NULL = the decision is not about a specific file.';
COMMENT ON COLUMN orders.order_item_decisions.supersedes_id IS 'Earlier decision this row corrects (orders.order_item_decisions). NULL = original decision, not a correction.';
COMMENT ON COLUMN orders.order_item_decisions.idempotency_key IS 'Client- or server-generated key that makes recording idempotent (Relu actions require one; other channels generate one), unique per tenant.';
COMMENT ON COLUMN orders.order_item_decisions.content_hash IS 'SHA-256 of the canonical decision content at recording time, referenced by compliance.electronic_signatures when the decision is signed. NULL = no signature-grade hash taken (e.g. migrated or verbal decisions).';
COMMENT ON COLUMN orders.order_item_decisions.decided_at IS 'UTC instant the client made the decision (for verbal decisions, as reported by staff).';
COMMENT ON COLUMN orders.order_item_decisions.created_at IS 'UTC instant the row was recorded. [AUDIT]';
COMMENT ON COLUMN orders.order_item_decisions.created_by_user_id IS 'iam.users.id of the staff member who recorded it (verbal, CP). No FK by design (audit actor). NULL = recorded by the client directly or by the system. [AUDIT]';
COMMENT ON CONSTRAINT pk_order_item_decisions ON orders.order_item_decisions IS 'One row per decision.';
COMMENT ON CONSTRAINT uq_order_item_decisions__uuid ON orders.order_item_decisions IS 'The public decision identifier is globally unique.';
COMMENT ON CONSTRAINT uq_order_item_decisions__tenant_id__idempotency_key ON orders.order_item_decisions IS 'A retried submission with the same idempotency key cannot record a second decision.';
COMMENT ON CONSTRAINT fk_order_item_decisions__order_item_id ON orders.order_item_decisions IS 'Decisions are regulated records; an item with decisions cannot be deleted.';
COMMENT ON CONSTRAINT fk_order_item_decisions__confirmation_link_id ON orders.order_item_decisions IS 'The link used is evidence of the decision and cannot be deleted.';
COMMENT ON CONSTRAINT fk_order_item_decisions__supersedes_id ON orders.order_item_decisions IS 'A corrected decision stays referenced by its correction.';
COMMENT ON CONSTRAINT ck_order_item_decisions__decision_kind ON orders.order_item_decisions IS 'Decision kind is one of the specified gate outcomes.';
COMMENT ON CONSTRAINT ck_order_item_decisions__channel ON orders.order_item_decisions IS 'Channel is email_link, connect, cp, verbal or api.';
COMMENT ON CONSTRAINT ck_order_item_decisions__one_actor ON orders.order_item_decisions IS 'Exactly one decider is recorded: a user or a contact, never both, never neither.';
COMMENT ON CONSTRAINT ck_order_item_decisions__link_iff_email_channel ON orders.order_item_decisions IS 'A decision through an e-mail link names the link, and only e-mail-link decisions name one.';
COMMENT ON CONSTRAINT ck_order_item_decisions__amendment_has_notes ON orders.order_item_decisions IS 'Requesting amendments requires notes saying what to change (Final AoX, Relu).';
COMMENT ON CONSTRAINT ck_order_item_decisions__not_self_superseding ON orders.order_item_decisions IS 'A decision cannot correct itself.';
COMMENT ON INDEX orders.ix_order_item_decisions__order_item_id__decided_at IS 'Decision history of an item, newest first (counters such as try-in redo count derive from it); covers the item FK.';
COMMENT ON INDEX orders.ix_order_item_decisions__tenant_id__created_at__id IS 'Stable keyset pagination of decisions (response-time and amendment reports).';
COMMENT ON INDEX orders.uq_order_item_decisions__confirmation_link_id IS 'A confirmation link records at most one decision (single use); covers the link FK.';
COMMENT ON INDEX orders.uq_order_item_decisions__supersedes_id IS 'A decision is corrected at most once (corrections chain); covers the self FK.';
COMMENT ON INDEX orders.ix_order_item_decisions__actor_user_id IS 'Decisions by a user; covers the FK.';
COMMENT ON INDEX orders.ix_order_item_decisions__actor_contact_id IS 'Decisions by a client contact; covers the FK.';
COMMENT ON INDEX orders.ix_order_item_decisions__subject_document_id IS 'Decisions about a file; covers the document FK.';
COMMENT ON INDEX orders.ix_order_item_decisions__workflow_state_id IS 'Covers the workflow-state FK.';

CREATE TRIGGER trg_order_item_decisions__append_only BEFORE UPDATE OR DELETE ON orders.order_item_decisions
    FOR EACH ROW EXECUTE FUNCTION core.fn_reject_mutation();
COMMENT ON TRIGGER trg_order_item_decisions__append_only ON orders.order_item_decisions IS 'Rejects UPDATE and DELETE: decisions are append-only regulated records; corrections are new rows with supersedes_id (core.fn_reject_mutation).';


-- =============================================================================
-- orders.order_item_dependencies
-- =============================================================================
CREATE TABLE orders.order_item_dependencies (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id           bigint NOT NULL DEFAULT core.fn_current_tenant(),
    order_item_id       bigint NOT NULL,
    depends_on_item_id  bigint NOT NULL,
    dependency_kind     varchar(20) NOT NULL,
    is_enforced         boolean NOT NULL DEFAULT false,
    note                varchar(255),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    created_by_user_id  bigint,
    updated_by_user_id  bigint,
    CONSTRAINT pk_order_item_dependencies PRIMARY KEY (id),
    CONSTRAINT uq_order_item_dependencies__item__depends_on UNIQUE (order_item_id, depends_on_item_id),
    CONSTRAINT fk_order_item_dependencies__order_item_id FOREIGN KEY (order_item_id) REFERENCES orders.order_items (id) ON DELETE CASCADE,
    CONSTRAINT fk_order_item_dependencies__depends_on_item_id FOREIGN KEY (depends_on_item_id) REFERENCES orders.order_items (id) ON DELETE CASCADE,
    CONSTRAINT ck_order_item_dependencies__not_self CHECK (order_item_id <> depends_on_item_id),
    CONSTRAINT ck_order_item_dependencies__kind CHECK (dependency_kind IN ('blocks', 'starts_after'))
);
CREATE INDEX ix_order_item_dependencies__depends_on_item_id ON orders.order_item_dependencies (depends_on_item_id);

COMMENT ON TABLE orders.order_item_dependencies IS 'Sequencing between items of a case (digest 03 X6): FMP/GFMP after the other services and before final restorations, Ti bar approved before Zirconia when delivered sequentially, GFMR before GFMP. One row per ordered pair (item depends on another item). Advisory by default (FMP US-01: sequencing could not yet be restricted); is_enforced makes the V100 workflow check reject transitions that break it.';
COMMENT ON COLUMN orders.order_item_dependencies.id IS 'Surrogate key of the dependency; system-generated.';
COMMENT ON COLUMN orders.order_item_dependencies.tenant_id IS 'Tenant that owns both items; row-level security scope.';
COMMENT ON COLUMN orders.order_item_dependencies.order_item_id IS 'Dependent item (orders.order_items): the one that must wait.';
COMMENT ON COLUMN orders.order_item_dependencies.depends_on_item_id IS 'Item it waits for (orders.order_items); may be on another order of the same case.';
COMMENT ON COLUMN orders.order_item_dependencies.dependency_kind IS 'Kind of wait: ''blocks'' = the depends-on item must be completed (or approved) before the dependent item may be completed or shipped; ''starts_after'' = the dependent item may not start work until the depends-on item is completed. Exact trigger states per service TO CONFIRM.';
COMMENT ON COLUMN orders.order_item_dependencies.is_enforced IS 'true = workflow transitions that break the dependency are rejected; false = advisory, shown as a warning only.';
COMMENT ON COLUMN orders.order_item_dependencies.note IS 'Why the dependency exists, for staff. NULL = created by a rule, no note.';
COMMENT ON COLUMN orders.order_item_dependencies.created_at IS 'UTC instant the dependency was created. [AUDIT]';
COMMENT ON COLUMN orders.order_item_dependencies.updated_at IS 'UTC instant of the last change (kind or enforcement); maintained by trg_order_item_dependencies__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN orders.order_item_dependencies.created_by_user_id IS 'iam.users.id of the creator. No FK by design (audit actor). NULL = created by a rule or the system. [AUDIT]';
COMMENT ON COLUMN orders.order_item_dependencies.updated_by_user_id IS 'iam.users.id of the last editor. No FK by design (audit actor). NULL = never updated or system. [AUDIT]';
COMMENT ON CONSTRAINT pk_order_item_dependencies ON orders.order_item_dependencies IS 'One row per dependency.';
COMMENT ON CONSTRAINT uq_order_item_dependencies__item__depends_on ON orders.order_item_dependencies IS 'An item depends on another given item at most once; also covers the dependent-item FK.';
COMMENT ON CONSTRAINT fk_order_item_dependencies__order_item_id ON orders.order_item_dependencies IS 'Link row: goes with the dependent item.';
COMMENT ON CONSTRAINT fk_order_item_dependencies__depends_on_item_id ON orders.order_item_dependencies IS 'Link row: goes with the item depended on.';
COMMENT ON CONSTRAINT ck_order_item_dependencies__not_self ON orders.order_item_dependencies IS 'An item cannot depend on itself (longer cycles are rejected by the V100 dependency function).';
COMMENT ON CONSTRAINT ck_order_item_dependencies__kind ON orders.order_item_dependencies IS 'Dependency kind is blocks or starts_after.';
COMMENT ON INDEX orders.ix_order_item_dependencies__depends_on_item_id IS 'Items waiting on a given item (release them when it completes); covers the FK.';

CREATE TRIGGER trg_order_item_dependencies__touch_updated_at BEFORE UPDATE ON orders.order_item_dependencies
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_order_item_dependencies__touch_updated_at ON orders.order_item_dependencies IS 'Sets updated_at and updated_by_user_id on every update (core.fn_touch_updated_at).';


-- =============================================================================
-- orders.order_item_assignments
-- =============================================================================
CREATE TABLE orders.order_item_assignments (
    id                   bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id            bigint NOT NULL DEFAULT core.fn_current_tenant(),
    order_item_id        bigint NOT NULL,
    assigned_to_user_id  bigint,
    assigned_to_team_id  bigint,
    assignment_role_id   bigint,
    assigned_by_user_id  bigint,
    assigned_at          timestamptz NOT NULL DEFAULT now(),
    unassigned_at        timestamptz,
    reason               varchar(255),
    created_at           timestamptz NOT NULL DEFAULT now(),
    updated_at           timestamptz NOT NULL DEFAULT now(),
    created_by_user_id   bigint,
    updated_by_user_id   bigint,
    CONSTRAINT pk_order_item_assignments PRIMARY KEY (id),
    CONSTRAINT fk_order_item_assignments__order_item_id FOREIGN KEY (order_item_id) REFERENCES orders.order_items (id) ON DELETE RESTRICT,
    CONSTRAINT ck_order_item_assignments__one_assignee CHECK (num_nonnulls(assigned_to_user_id, assigned_to_team_id) = 1),
    CONSTRAINT ck_order_item_assignments__unassigned_after_assigned CHECK (unassigned_at IS NULL OR unassigned_at >= assigned_at)
);
CREATE UNIQUE INDEX uq_order_item_assignments__order_item_id__open ON orders.order_item_assignments (order_item_id) WHERE unassigned_at IS NULL;
CREATE INDEX ix_order_item_assignments__order_item_id__assigned_at ON orders.order_item_assignments (order_item_id, assigned_at DESC);
CREATE INDEX ix_order_item_assignments__assigned_to_user_id__assigned_at ON orders.order_item_assignments (assigned_to_user_id, assigned_at DESC) WHERE assigned_to_user_id IS NOT NULL;
CREATE INDEX ix_order_item_assignments__assigned_to_team_id__assigned_at ON orders.order_item_assignments (assigned_to_team_id, assigned_at DESC) WHERE assigned_to_team_id IS NOT NULL;
CREATE INDEX ix_order_item_assignments__assignment_role_id ON orders.order_item_assignments (assignment_role_id) WHERE assignment_role_id IS NOT NULL;
CREATE INDEX ix_order_item_assignments__assigned_by_user_id ON orders.order_item_assignments (assigned_by_user_id) WHERE assigned_by_user_id IS NOT NULL;

COMMENT ON TABLE orders.order_item_assignments IS 'History of who an order item is assigned to (digest 03 X9): Final AoX "Restoration TO-DO" (prepper self-assigns in Prepping, designer self-assigns anywhere, supervisor assigns), fabrication-notes "Assign". One row per assignment period, from assigned_at until unassigned_at; at most one open assignment per item. Rows are closed, never deleted. orders.order_items.designer_user_id keeps the current designer for v2 compatibility.';
COMMENT ON COLUMN orders.order_item_assignments.id IS 'Surrogate key of the assignment period; system-generated.';
COMMENT ON COLUMN orders.order_item_assignments.tenant_id IS 'Tenant that owns the item; row-level security scope.';
COMMENT ON COLUMN orders.order_item_assignments.order_item_id IS 'Assigned item (orders.order_items).';
COMMENT ON COLUMN orders.order_item_assignments.assigned_to_user_id IS 'Staff user (iam.users) the item is assigned to. NULL = assigned to a team instead.';
COMMENT ON COLUMN orders.order_item_assignments.assigned_to_team_id IS 'Team (iam.teams) the item is assigned to. NULL = assigned to a user instead.';
COMMENT ON COLUMN orders.order_item_assignments.assignment_role_id IS 'Role the assignee works the item in (iam.roles: Prepper, Designer, Design QC). NULL = no role scope.';
COMMENT ON COLUMN orders.order_item_assignments.assigned_by_user_id IS 'Staff user (iam.users) who made the assignment (the assignee for a self-assignment, the supervisor otherwise). NULL = assigned by the system, or the assigner was removed.';
COMMENT ON COLUMN orders.order_item_assignments.assigned_at IS 'UTC instant the assignment started.';
COMMENT ON COLUMN orders.order_item_assignments.unassigned_at IS 'UTC instant the assignment ended (reassigned, released or item done). NULL = current assignment.';
COMMENT ON COLUMN orders.order_item_assignments.reason IS 'Why the item was assigned or reassigned. NULL = no reason given.';
COMMENT ON COLUMN orders.order_item_assignments.created_at IS 'UTC instant the row was recorded. [AUDIT]';
COMMENT ON COLUMN orders.order_item_assignments.updated_at IS 'UTC instant of the last change (closing the period); maintained by trg_order_item_assignments__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN orders.order_item_assignments.created_by_user_id IS 'iam.users.id of the creator. No FK by design (audit actor). NULL = system. [AUDIT]';
COMMENT ON COLUMN orders.order_item_assignments.updated_by_user_id IS 'iam.users.id of the last editor. No FK by design (audit actor). NULL = never updated or system. [AUDIT]';
COMMENT ON CONSTRAINT pk_order_item_assignments ON orders.order_item_assignments IS 'One row per assignment period.';
COMMENT ON CONSTRAINT fk_order_item_assignments__order_item_id ON orders.order_item_assignments IS 'Assignment history is retained: an item with assignments cannot be hard-deleted.';
COMMENT ON CONSTRAINT ck_order_item_assignments__one_assignee ON orders.order_item_assignments IS 'An assignment goes to exactly one user or one team.';
COMMENT ON CONSTRAINT ck_order_item_assignments__unassigned_after_assigned ON orders.order_item_assignments IS 'An assignment ends no earlier than it started.';
COMMENT ON INDEX orders.uq_order_item_assignments__order_item_id__open IS 'Rule and hot subset: an item has at most one current assignee (the TO-DO assignment field). TO CONFIRM if parallel assignments per role (prepper and designer at once) are needed.';
COMMENT ON INDEX orders.ix_order_item_assignments__order_item_id__assigned_at IS 'Assignment history of an item; covers the item FK.';
COMMENT ON INDEX orders.ix_order_item_assignments__assigned_to_user_id__assigned_at IS 'A user''s assignments ("my TO-DO"); covers the FK.';
COMMENT ON INDEX orders.ix_order_item_assignments__assigned_to_team_id__assigned_at IS 'A team''s assignments; covers the FK.';
COMMENT ON INDEX orders.ix_order_item_assignments__assignment_role_id IS 'Covers the role FK.';
COMMENT ON INDEX orders.ix_order_item_assignments__assigned_by_user_id IS 'Assignments made by a supervisor; covers the FK.';

CREATE TRIGGER trg_order_item_assignments__touch_updated_at BEFORE UPDATE ON orders.order_item_assignments
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_order_item_assignments__touch_updated_at ON orders.order_item_assignments IS 'Sets updated_at and updated_by_user_id on every update (core.fn_touch_updated_at).';


-- =============================================================================
-- orders.order_item_ai_plans
-- =============================================================================
CREATE TABLE orders.order_item_ai_plans (
    id                        bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id                 bigint NOT NULL DEFAULT core.fn_current_tenant(),
    order_item_id             bigint NOT NULL,
    planning_mode             varchar(10) NOT NULL DEFAULT 'manual',
    is_ai_eligible            boolean NOT NULL DEFAULT false,
    eligibility_reason        varchar(200),
    eligibility_segments      jsonb,
    largest_segment_size      smallint,
    eligibility_evaluated_at  timestamptz,
    ai_status                 varchar(20) NOT NULL DEFAULT 'not_applicable',
    ai_decision               varchar(30) NOT NULL DEFAULT 'undecided',
    ai_queued_at              timestamptz,
    ai_ready_at               timestamptz,
    ai_failed_at              timestamptz,
    ai_archived_at            timestamptz,
    relu_id                           varchar(255),
    printer_offset                    numeric(8,4),
    guide_thickness                   numeric(8,4),
    text_to_print                     text,
    guide_bar                         varchar(255),
    glue_holes                        boolean,
    implant_filters_folder            varchar(255),
    implant_filters_product_line      varchar(255),
    sleeve_filters_folder             varchar(255),
    sleeve_filters_product_line       varchar(255),
    waxup_filters_folder              varchar(255),
    surgical_kit_filters_folder       varchar(255),
    surgical_kit_filters_product_line varchar(255),
    lower_jaw                         varchar(255),
    upper_jaw                         varchar(255),
    volume                            varchar(255),
    facial_scan                       varchar(255),
    bite                              varchar(255),
    ai_actions_enabled                boolean NOT NULL DEFAULT true,
    legacy_id                 bigint,
    legacy_source             varchar(64),
    legacy_key                varchar(200),
    created_at                timestamptz NOT NULL DEFAULT now(),
    updated_at                timestamptz NOT NULL DEFAULT now(),
    created_by_user_id        bigint,
    updated_by_user_id        bigint,
    CONSTRAINT pk_order_item_ai_plans PRIMARY KEY (id),
    CONSTRAINT uq_order_item_ai_plans__order_item_id UNIQUE (order_item_id),
    CONSTRAINT fk_order_item_ai_plans__order_item_id FOREIGN KEY (order_item_id) REFERENCES orders.order_items (id) ON DELETE RESTRICT,
    CONSTRAINT ck_order_item_ai_plans__planning_mode CHECK (planning_mode IN ('ai', 'manual')),
    CONSTRAINT ck_order_item_ai_plans__ai_status CHECK (ai_status IN ('not_applicable', 'eligible', 'queued',
        'processing', 'ready', 'failed', 'archived')),
    CONSTRAINT ck_order_item_ai_plans__ai_decision CHECK (ai_decision IN ('undecided', 'ai_not_in_scope', 'ai_selected',
        'manual_selected', 'ai_rejected_clinic', 'ai_failed_fallback', 'ai_ready')),
    CONSTRAINT ck_order_item_ai_plans__largest_segment_positive CHECK (largest_segment_size IS NULL OR largest_segment_size > 0),
    CONSTRAINT ck_order_item_ai_plans__eligibility_evaluated CHECK (eligibility_evaluated_at IS NOT NULL
        OR (NOT is_ai_eligible AND eligibility_reason IS NULL AND eligibility_segments IS NULL AND largest_segment_size IS NULL)),
    CONSTRAINT ck_order_item_ai_plans__ai_mode_needs_eligibility CHECK (legacy_id IS NOT NULL OR planning_mode = 'manual' OR is_ai_eligible),
    CONSTRAINT ck_order_item_ai_plans__ready_after_queued CHECK (ai_ready_at IS NULL OR ai_queued_at IS NULL OR ai_ready_at >= ai_queued_at)
);
CREATE INDEX ix_order_item_ai_plans__tenant_id__ai_status__in_flight ON orders.order_item_ai_plans (tenant_id, ai_status, ai_queued_at)
    WHERE ai_status IN ('queued', 'processing');
CREATE UNIQUE INDEX uq_order_item_ai_plans__legacy ON orders.order_item_ai_plans (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE orders.order_item_ai_plans IS 'Relu AI implant planning state of a treatment-plan item (digest 03 section 14, Relu Viewer Integration v2.0): planning mode chosen by the doctor, AI eligibility computed from the chart, AI job status and the AI decision. One row per TP item that went through the Connect AI flow (1:1 with orders.order_items). The manual planning status is the item''s own status/workflow state; the Relu job id, viewer token and share state are in integration.external_references; webhooks in integration.webhook_events. Migrated from legacy OrderTPAI (Relu request parameters, typed columns) and the OrderTP flags is_ai (-> planning_mode ''ai'') and aiFailed (-> ai_status ''failed'', ai_decision ''ai_failed_fallback'').';
COMMENT ON COLUMN orders.order_item_ai_plans.id IS 'Surrogate key; system-generated.';
COMMENT ON COLUMN orders.order_item_ai_plans.tenant_id IS 'Tenant that owns the item; row-level security scope.';
COMMENT ON COLUMN orders.order_item_ai_plans.order_item_id IS 'Treatment-plan item planned (orders.order_items), one AI plan row per item.';
COMMENT ON COLUMN orders.order_item_ai_plans.planning_mode IS 'Planning mode the doctor chose on the Start step: ''ai'' = Relu AI plans, planners review; ''manual'' = planners plan by hand (default). Same service code either way; pricing conditions use it (AI = replication price per arch).';
COMMENT ON COLUMN orders.order_item_ai_plans.is_ai_eligible IS 'Result of the live eligibility rule: planned implant+crown or pontic sites form contiguous segments of at most 3 units each (several segments and both arches allowed), not full edentulous; Connect-created cases only. false until evaluated.';
COMMENT ON COLUMN orders.order_item_ai_plans.eligibility_reason IS 'Reason returned with the eligibility result (why not eligible, or the rule that passed). NULL = eligibility never evaluated (CP-created, integration or legacy cases).';
COMMENT ON COLUMN orders.order_item_ai_plans.eligibility_segments IS 'Segment structure computed from the chart (arches, Universal tooth numbers per segment) as JSON, persisted when leaving the Chart step; displayed only. NULL = never evaluated.';
COMMENT ON COLUMN orders.order_item_ai_plans.largest_segment_size IS 'Number of units in the largest contiguous segment. NULL = never evaluated.';
COMMENT ON COLUMN orders.order_item_ai_plans.eligibility_evaluated_at IS 'UTC instant eligibility was last computed and persisted. NULL = never evaluated.';
COMMENT ON COLUMN orders.order_item_ai_plans.ai_status IS 'Relu AI job status (aiStatus): ''not_applicable'' = AI not offered for this item; ''eligible'' = AI can be or was chosen, job not started (stays so after submit until upload completes); ''queued'' = upload done, job requested; ''processing'' = Relu is planning; ''ready'' = plan ready (Done webhook), charging trigger fires; ''failed'' = job failed or timed out (>1 h), falls back to manual; ''archived'' = clinic chose FT session or amendment, AI plan closed.';
COMMENT ON COLUMN orders.order_item_ai_plans.ai_decision IS 'AI decision state (aiDecision): ''undecided'' = no choice yet; ''ai_not_in_scope'' = not eligible for AI; ''ai_selected'' = doctor chose AI; ''manual_selected'' = doctor chose manual; ''ai_rejected_clinic'' = clinic rejected the AI plan (FT session or amendment); ''ai_failed_fallback'' = AI failed, manual planning took over; ''ai_ready'' = TO CONFIRM: appears in the Relu decision state machine but not in the aiDecision enum (digest 03 A4), allowed until the business decides.';
COMMENT ON COLUMN orders.order_item_ai_plans.ai_queued_at IS 'UTC instant the AI job was requested from Relu (exactly once per order). NULL = never queued.';
COMMENT ON COLUMN orders.order_item_ai_plans.ai_ready_at IS 'UTC instant the AI plan became ready; also sets the TP item''s sent time for charging. NULL = not ready.';
COMMENT ON COLUMN orders.order_item_ai_plans.ai_failed_at IS 'UTC instant the AI job failed or timed out. NULL = not failed.';
COMMENT ON COLUMN orders.order_item_ai_plans.ai_archived_at IS 'UTC instant the AI plan was archived (clinic rejected it). NULL = not archived.';
COMMENT ON COLUMN orders.order_item_ai_plans.relu_id IS 'Relu''s own case/order id for this plan (legacy OrderTPAI.reluId); also recorded in integration.external_references, kept here for the AI plan. NULL = not set in the Relu request.';
COMMENT ON COLUMN orders.order_item_ai_plans.printer_offset IS 'Printer offset sent to Relu for guide design, in mm (legacy OrderTPAI.printer_offset). NULL = not set in the Relu request.';
COMMENT ON COLUMN orders.order_item_ai_plans.guide_thickness IS 'Surgical guide thickness in mm sent to Relu (legacy OrderTPAI.guide_thickness). NULL = not set in the Relu request.';
COMMENT ON COLUMN orders.order_item_ai_plans.text_to_print IS 'Text to emboss on the guide (legacy OrderTPAI.text_to_print); may contain the patient''s name or initials. NULL = not set in the Relu request. [PHI-RISK]';
COMMENT ON COLUMN orders.order_item_ai_plans.guide_bar IS 'Guide bar option sent to Relu (legacy OrderTPAI.guide_bar). NULL = not set in the Relu request.';
COMMENT ON COLUMN orders.order_item_ai_plans.glue_holes IS 'Whether the guide gets glue holes (legacy OrderTPAI.glue_holes tinyint). Nullable on purpose: legacy distinguishes unset from no. NULL = not set in the Relu request.';
COMMENT ON COLUMN orders.order_item_ai_plans.implant_filters_folder IS 'Relu implant-library filter: folder (manufacturer) chosen (legacy OrderTPAI.implant_filters_folder). NULL = not set in the Relu request.';
COMMENT ON COLUMN orders.order_item_ai_plans.implant_filters_product_line IS 'Relu implant-library filter: product line (legacy OrderTPAI.implant_filters_productLine). NULL = not set in the Relu request.';
COMMENT ON COLUMN orders.order_item_ai_plans.sleeve_filters_folder IS 'Relu sleeve-library filter: folder (legacy OrderTPAI.sleeve_filters_folder). NULL = not set in the Relu request.';
COMMENT ON COLUMN orders.order_item_ai_plans.sleeve_filters_product_line IS 'Relu sleeve-library filter: product line (legacy OrderTPAI.sleeve_filters_productLine). NULL = not set in the Relu request.';
COMMENT ON COLUMN orders.order_item_ai_plans.waxup_filters_folder IS 'Relu wax-up library filter: folder (legacy OrderTPAI.waxup_filters_folder). NULL = not set in the Relu request.';
COMMENT ON COLUMN orders.order_item_ai_plans.surgical_kit_filters_folder IS 'Relu surgical-kit library filter: folder (legacy OrderTPAI.surgical_kit_filters_folder). NULL = not set in the Relu request.';
COMMENT ON COLUMN orders.order_item_ai_plans.surgical_kit_filters_product_line IS 'Relu surgical-kit library filter: product line (legacy OrderTPAI.surgical_kit_filters_productLine). NULL = not set in the Relu request.';
COMMENT ON COLUMN orders.order_item_ai_plans.lower_jaw IS 'File identifier of the lower-jaw scan sent to Relu (legacy OrderTPAI.lower_jaw); file names may contain patient names. NULL = not set in the Relu request. [PHI-RISK]';
COMMENT ON COLUMN orders.order_item_ai_plans.upper_jaw IS 'File identifier of the upper-jaw scan sent to Relu (legacy OrderTPAI.upper_jaw); file names may contain patient names. NULL = not set in the Relu request. [PHI-RISK]';
COMMENT ON COLUMN orders.order_item_ai_plans.volume IS 'File identifier of the CBCT volume sent to Relu (legacy OrderTPAI.volume); file names may contain patient names. NULL = not set in the Relu request. [PHI-RISK]';
COMMENT ON COLUMN orders.order_item_ai_plans.facial_scan IS 'File identifier of the facial scan sent to Relu (legacy OrderTPAI.facial_scan); file names may contain patient names. NULL = not set in the Relu request. [PHI-RISK]';
COMMENT ON COLUMN orders.order_item_ai_plans.bite IS 'File identifier of the bite scan sent to Relu (legacy OrderTPAI.bite); file names may contain patient names. NULL = not set in the Relu request. [PHI-RISK]';
COMMENT ON COLUMN orders.order_item_ai_plans.ai_actions_enabled IS 'true = the clinic''s one-shot AI actions (FT session, request amendment, proceed with guide fabrication) are available on this plan; false = disabled (an action was taken or staff turned them off). Migrated from legacy OrderTPAI.AiActions (default 1).';
COMMENT ON COLUMN orders.order_item_ai_plans.legacy_id IS 'OrderTPAI.id this row was migrated from (OrderTPAI is keyed to the TP sub-order by TPID, which resolves order_item_id). For TP items with only the OrderTP is_ai/aiFailed flags and no OrderTPAI row, legacy_source = ''OrderTP'' and legacy_id = OrderTP.ID. NULL = created in threeddx3.';
COMMENT ON COLUMN orders.order_item_ai_plans.legacy_source IS 'Legacy table (''OrderTPAI'' or ''OrderTP''). NULL = created in threeddx3.';
COMMENT ON COLUMN orders.order_item_ai_plans.legacy_key IS 'Composite legacy key when one id is not enough. NULL = legacy_id alone identifies the row.';
COMMENT ON COLUMN orders.order_item_ai_plans.created_at IS 'UTC instant the row was created. [AUDIT]';
COMMENT ON COLUMN orders.order_item_ai_plans.updated_at IS 'UTC instant of the last change; maintained by trg_order_item_ai_plans__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN orders.order_item_ai_plans.created_by_user_id IS 'iam.users.id of the creator. No FK by design (audit actor). NULL = system, migration or portal. [AUDIT]';
COMMENT ON COLUMN orders.order_item_ai_plans.updated_by_user_id IS 'iam.users.id of the last editor. No FK by design (audit actor). NULL = system (webhook) or never updated. [AUDIT]';
COMMENT ON CONSTRAINT pk_order_item_ai_plans ON orders.order_item_ai_plans IS 'One row per AI plan.';
COMMENT ON CONSTRAINT uq_order_item_ai_plans__order_item_id ON orders.order_item_ai_plans IS 'A treatment-plan item has at most one AI plan state (1:1); covers the item FK.';
COMMENT ON CONSTRAINT fk_order_item_ai_plans__order_item_id ON orders.order_item_ai_plans IS 'AI plan state is retained with the item; an item with AI state cannot be hard-deleted.';
COMMENT ON CONSTRAINT ck_order_item_ai_plans__planning_mode ON orders.order_item_ai_plans IS 'Planning mode is ai or manual.';
COMMENT ON CONSTRAINT ck_order_item_ai_plans__ai_status ON orders.order_item_ai_plans IS 'AI status is one of the Relu v2.0 aiStatus values.';
COMMENT ON CONSTRAINT ck_order_item_ai_plans__ai_decision ON orders.order_item_ai_plans IS 'AI decision is one of the Relu v2.0 aiDecision values, plus ai_ready (TO CONFIRM, digest 03 A4).';
COMMENT ON CONSTRAINT ck_order_item_ai_plans__largest_segment_positive ON orders.order_item_ai_plans IS 'The largest segment has at least one unit.';
COMMENT ON CONSTRAINT ck_order_item_ai_plans__eligibility_evaluated ON orders.order_item_ai_plans IS 'Eligibility results (flag, reason, segments) exist only once eligibility has been evaluated.';
COMMENT ON CONSTRAINT ck_order_item_ai_plans__ai_mode_needs_eligibility ON orders.order_item_ai_plans IS 'AI planning can be chosen only for an eligible case. Migrated rows are exempt (legacy computed no eligibility).';
COMMENT ON CONSTRAINT ck_order_item_ai_plans__ready_after_queued ON orders.order_item_ai_plans IS 'A plan becomes ready no earlier than its job was queued.';
COMMENT ON INDEX orders.ix_order_item_ai_plans__tenant_id__ai_status__in_flight IS 'Hot subset: AI jobs queued or processing, for the backup polling job (every 10-30 min) and the 1-hour timeout fallback.';
COMMENT ON INDEX orders.uq_order_item_ai_plans__legacy IS 'Every migrated AI plan is traceable and cannot be loaded twice.';

CREATE TRIGGER trg_order_item_ai_plans__touch_updated_at BEFORE UPDATE ON orders.order_item_ai_plans
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_order_item_ai_plans__touch_updated_at ON orders.order_item_ai_plans IS 'Sets updated_at and updated_by_user_id on every update (core.fn_touch_updated_at).';


-- =============================================================================
-- orders.pre_shipping_instructions
-- =============================================================================
CREATE TABLE orders.pre_shipping_instructions (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id           bigint NOT NULL DEFAULT core.fn_current_tenant(),
    order_id            bigint NOT NULL,
    order_item_id       bigint,
    version_no          integer NOT NULL,
    body                text NOT NULL,
    mail_to             text,
    author_user_id      bigint,
    legacy_id           bigint,
    legacy_source       varchar(64),
    legacy_key          varchar(200),
    created_at          timestamptz NOT NULL DEFAULT now(),
    created_by_user_id  bigint,
    CONSTRAINT pk_pre_shipping_instructions PRIMARY KEY (id),
    CONSTRAINT uq_pre_shipping_instructions__order__item__version UNIQUE NULLS NOT DISTINCT (order_id, order_item_id, version_no),
    CONSTRAINT fk_pre_shipping_instructions__order_id FOREIGN KEY (order_id) REFERENCES orders.orders (id) ON DELETE RESTRICT,
    CONSTRAINT fk_pre_shipping_instructions__order_item_id FOREIGN KEY (order_item_id) REFERENCES orders.order_items (id) ON DELETE RESTRICT,
    CONSTRAINT ck_pre_shipping_instructions__version_positive CHECK (version_no >= 1),
    CONSTRAINT ck_pre_shipping_instructions__body_not_blank CHECK (btrim(body) <> '')
);
CREATE INDEX ix_pre_shipping_instructions__order_item_id ON orders.pre_shipping_instructions (order_item_id) WHERE order_item_id IS NOT NULL;
CREATE INDEX ix_pre_shipping_instructions__author_user_id ON orders.pre_shipping_instructions (author_user_id) WHERE author_user_id IS NOT NULL;
CREATE UNIQUE INDEX uq_pre_shipping_instructions__legacy ON orders.pre_shipping_instructions (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;

COMMENT ON TABLE orders.pre_shipping_instructions IS 'Versioned pre-shipping instructions (PSI) for an order or one of its items: what shipping/production must do before dispatch (legacy preShippingInstruction; digest 04). One row per version; an edit inserts the next version_no, the highest version is current. Append-only: UPDATE and DELETE rejected by trigger. orders.orders.pre_shipping_instructions mirrors the current text for v2 compatibility. Contains PHI-risk free text.';
COMMENT ON COLUMN orders.pre_shipping_instructions.id IS 'Surrogate key of the version; system-generated.';
COMMENT ON COLUMN orders.pre_shipping_instructions.tenant_id IS 'Tenant that owns the order; row-level security scope.';
COMMENT ON COLUMN orders.pre_shipping_instructions.order_id IS 'Order the instruction applies to (orders.orders).';
COMMENT ON COLUMN orders.pre_shipping_instructions.order_item_id IS 'Item the instruction applies to (legacy subID). NULL = applies to the whole order (legacy subID 0).';
COMMENT ON COLUMN orders.pre_shipping_instructions.version_no IS 'Version number, 1-based, per order and item; the highest is current. Assigned by the application (and by the ETL in legacy creation order).';
COMMENT ON COLUMN orders.pre_shipping_instructions.body IS 'Instruction text; may name the patient. [PHI-RISK]';
COMMENT ON COLUMN orders.pre_shipping_instructions.mail_to IS 'E-mail addresses the instruction was sent to, as recorded (legacy MailTo, comma-separated). NULL = not e-mailed. [PII]';
COMMENT ON COLUMN orders.pre_shipping_instructions.author_user_id IS 'Staff user (iam.users) who wrote this version (legacy creatorID). NULL = written by the system, or the legacy creator could not be mapped.';
COMMENT ON COLUMN orders.pre_shipping_instructions.legacy_id IS 'preShippingInstruction.id. NULL = written in threeddx3.';
COMMENT ON COLUMN orders.pre_shipping_instructions.legacy_source IS 'Legacy table (''preShippingInstruction''). NULL = written in threeddx3.';
COMMENT ON COLUMN orders.pre_shipping_instructions.legacy_key IS 'Composite legacy key when one id is not enough. NULL = legacy_id alone identifies the row.';
COMMENT ON COLUMN orders.pre_shipping_instructions.created_at IS 'UTC instant this version was written (legacy CreatedAt for migrated rows). [AUDIT]';
COMMENT ON COLUMN orders.pre_shipping_instructions.created_by_user_id IS 'iam.users.id of the session user who inserted the row. No FK by design (audit actor). NULL = system or migration. [AUDIT]';
COMMENT ON CONSTRAINT pk_pre_shipping_instructions ON orders.pre_shipping_instructions IS 'One row per instruction version.';
COMMENT ON CONSTRAINT uq_pre_shipping_instructions__order__item__version ON orders.pre_shipping_instructions IS 'Each version number is used once per order and item (order-level instructions, item NULL, count as one series); also covers the order FK.';
COMMENT ON CONSTRAINT fk_pre_shipping_instructions__order_id ON orders.pre_shipping_instructions IS 'Instruction history is retained: an order with instructions cannot be hard-deleted.';
COMMENT ON CONSTRAINT fk_pre_shipping_instructions__order_item_id ON orders.pre_shipping_instructions IS 'Instruction history is retained: an item with instructions cannot be hard-deleted.';
COMMENT ON CONSTRAINT ck_pre_shipping_instructions__version_positive ON orders.pre_shipping_instructions IS 'Version numbers start at 1.';
COMMENT ON CONSTRAINT ck_pre_shipping_instructions__body_not_blank ON orders.pre_shipping_instructions IS 'An instruction has text; clearing an instruction is not a version.';
COMMENT ON INDEX orders.ix_pre_shipping_instructions__order_item_id IS 'Instructions of an item; covers the item FK.';
COMMENT ON INDEX orders.ix_pre_shipping_instructions__author_user_id IS 'Covers the author FK.';
COMMENT ON INDEX orders.uq_pre_shipping_instructions__legacy IS 'Every migrated instruction is traceable to its legacy row and cannot be loaded twice.';

CREATE TRIGGER trg_pre_shipping_instructions__append_only BEFORE UPDATE OR DELETE ON orders.pre_shipping_instructions
    FOR EACH ROW EXECUTE FUNCTION core.fn_reject_mutation();
COMMENT ON TRIGGER trg_pre_shipping_instructions__append_only ON orders.pre_shipping_instructions IS 'Rejects UPDATE and DELETE: instruction versions are append-only; an edit is a new version (core.fn_reject_mutation).';
